  let paneCloseBusy = false;
  let paneMenuId = null;
  let paneHoverId = null;
  let paneHighlightFrame = 0;
  let paneLastPaint = 0;

  function findNativePane(id) {
    const views = document.querySelectorAll?.('[data-testid="conversation-view"][data-cascade-id]') || [];
    const view = Array.from(views).find(node => sameRouteId(node.getAttribute('data-cascade-id'), id));
    const content = view?.closest?.('[data-pane-id]');
    const paneId = content?.getAttribute('data-pane-id');
    if (!paneId) return null;
    let container = content;
    let close = null;
    while (container?.getAttribute('data-pane-id') === paneId) {
      close = Array.from(container.querySelectorAll('[data-testid="close-pane-button"]'))
        .find(button => button.closest('[data-pane-id]')?.getAttribute('data-pane-id') === paneId);
      if (close) break;
      const parent = container.parentElement?.closest('[data-pane-id]');
      if (parent?.getAttribute('data-pane-id') !== paneId) break;
      container = parent;
    }
    return { content, container, close };
  }

  function setScopeTopLayer(node, open) {
    if (!node) return;
    if (!open && !node.hidden) {
      try { node.hidePopover?.(); } catch { }
    }
    if (open && node.hidden) {
      node.hidden = false;
      try { node.showPopover?.(); } catch { }
    }
    node.hidden = !open;
  }

  function dismissPaneMenu() {
    paneMenuId = null;
    setScopeTopLayer(el('ctx-scope-menu'), false);
  }

  function syncPaneHighlights() {
    if (paneHighlightFrame || typeof requestAnimationFrame !== 'function') return;
    paneHighlightFrame = requestAnimationFrame(now => {
      paneHighlightFrame = 0;
      const overlay = el('ctx-scope-highlights');
      if (!overlay) return;
      const visible = !state.disposed && !el('panel')?.hidden && !el('pane-ctx-session')?.hidden && !el('ctx-scope-bar')?.hidden;
      if (!visible) {
        paneHoverId = null;
        paneBatch = false;
        paneCloseSelection.clear();
        dismissPaneMenu();
        syncPaneBatchControls();
      }
      const hover = paneMenuId || paneHoverId;
      const marked = visible ? new Set([...paneCloseSelection, hover].filter(Boolean)) : new Set();
      if (marked.size && now - paneLastPaint < 48) {
        syncPaneHighlights();
        return;
      }
      paneLastPaint = now;
      const boxes = [];
      for (const id of marked) {
        const pane = findNativePane(id);
        const rect = pane?.container.getBoundingClientRect();
        if (!rect?.width || !rect.height) continue;
        const verticalPad = Math.min(4, rect.height / 2);
        const box = document.createElement('div');
        box.className = 'ctx-scope-highlight';
        box.style.left = `${Math.max(0, rect.left + 2)}px`;
        box.style.width = `${Math.max(0, Math.min(window.innerWidth, rect.right) - Math.max(0, rect.left + 2) - 2)}px`;
        box.style.top = `${Math.max(0, rect.top + verticalPad)}px`;
        box.style.height = `${Math.max(0, Math.min(window.innerHeight, rect.bottom) - Math.max(0, rect.top + verticalPad) - verticalPad)}px`;
        if (id === hover) {
          const row = Array.from(document.querySelectorAll('[data-testid="conversation-row-sidebar"][data-cascade-id]'))
            .find(node => sameRouteId(node.getAttribute('data-cascade-id'), id));
          const message = pane.content.querySelector('[data-testid="user-message"], [data-testid="user-input"], [data-testid="chat-message-user"]');
          const title = (row?.textContent?.trim() || message?.textContent?.trim() || '').replace(/[（）()]/g, '').slice(0, 180);
          if (title) {
            const label = document.createElement('span');
            label.textContent = title;
            box.appendChild(label);
          }
        }
        boxes.push(box);
      }
      const signature = boxes.map(box => box.getAttribute('style') + box.textContent).join('|');
      if (overlay._paneSig !== signature) {
        overlay.replaceChildren(...boxes);
        overlay._paneSig = signature;
      }
      setScopeTopLayer(overlay, boxes.length > 0);
      if (marked.size) syncPaneHighlights();
    });
  }

  function syncPaneBatchControls(layout = state.layout || parseConversationLayout()) {
    const toggle = el('ctx-scope-batch');
    const actions = el('ctx-scope-batch-actions');
    const close = el('ctx-scope-batch-close');
    if (!toggle || !actions || !close) return;
    for (const id of paneCloseSelection) {
      if (!layout.panes.includes(id)) paneCloseSelection.delete(id);
    }
    toggle.hidden = layout.panes.length < 2;
    if (toggle.hidden) {
      paneBatch = false;
      paneCloseSelection.clear();
    }
    toggle.setAttribute('aria-pressed', String(paneBatch));
    actions.hidden = !paneBatch;
    close.disabled = paneCloseBusy || !paneCloseSelection.size;
    close.textContent = t('scope.closeSelected', { n: Math.min(paneCloseSelection.size, Math.max(0, layout.panes.length - 1)) });
    for (const pill of el('ctx-scope-pills')?.children || []) {
      if (pill.getAttribute?.('data-scope-role') !== 'pane') continue;
      const selected = paneCloseSelection.has(pill.getAttribute('data-scope-id'));
      pill.classList?.toggle?.('is-marked', selected);
      if (paneBatch) {
        pill.setAttribute('role', 'checkbox');
        pill.setAttribute('aria-checked', String(selected));
        pill.removeAttribute('aria-selected');
      }
    }
  }

  async function closeNativePanes(ids, keepId) {
    if (paneCloseBusy) return;
    paneCloseBusy = true;
    syncPaneBatchControls();
    let skipped = false;
    try {
      for (const id of ids) {
        const { panes } = parseConversationLayout();
        if (!panes.includes(id)) continue;
        if (panes.length < 2 || id === keepId) { skipped = true; continue; }
        const button = findNativePane(id)?.close;
        if (!button?.isConnected || button.disabled) { skipped = true; continue; }
        button.click();
        for (let retry = 0; retry < 24 && parseConversationLayout().panes.includes(id); retry++) {
          await new Promise(resolve => setTimeout(resolve, 50));
        }
        if (parseConversationLayout().panes.includes(id)) { skipped = true; break; }
      }
    } finally {
      paneCloseBusy = false;
      paneBatch = false;
      paneCloseSelection.clear();
      lastScopeRenderSig = '';
      tick();
      syncPaneHighlights();
      if (skipped) showSpeedToast(t('scope.closeSkipped'));
    }
  }

  function openPaneMenu(event, item) {
    if (!findNativePane(item.id)) return;
    event.preventDefault();
    const menu = el('ctx-scope-menu');
    if (!menu) return;
    paneMenuId = item.id;
    const { panes } = parseConversationLayout();
    for (const button of menu.querySelectorAll('[data-pane-action]')) {
      const action = button.getAttribute('data-pane-action');
      button.disabled = action === 'right' ? panes.indexOf(item.id) === panes.length - 1 : action !== 'focus' && panes.length < 2;
    }
    menu.style.left = '0px';
    menu.style.top = '0px';
    setScopeTopLayer(menu, true);
    const anchor = event.currentTarget.getBoundingClientRect();
    menu.style.left = `${Math.max(4, Math.min(event.clientX || anchor.left, window.innerWidth - menu.offsetWidth - 4))}px`;
    menu.style.top = `${Math.max(4, Math.min(event.clientY || anchor.bottom, window.innerHeight - menu.offsetHeight - 4))}px`;
    menu.querySelector('button')?.focus();
    syncPaneHighlights();
  }

  function renderConversationScopeUI(force = false) {
    const layout = state.layout || parseConversationLayout();
    const activeId = state.route || null;
    const activeTarget = (layout?.isMultiSession && activeId)
      ? (layout.targets.find(item => sameRouteId(item.id, activeId)) || null)
      : null;
    const isLocked = Boolean(state.pinnedViewRoute && activeTarget);
    const sig = `${layout?.layoutKey || ''}|${activeId || ''}|${isLocked ? 1 : 0}|${currentPanelLanguage}`;
    if (!force && sig === lastScopeRenderSig) return;
    lastScopeRenderSig = sig;

    const badgeTag = el('badge-scope-tag');
    if (badgeTag) {
      const shortTag = !activeTarget ? ''
        : (activeTarget.role === 'sidechat' ? t('scope.badge.sideShort')
          : (layout.panes.length > 1 ? `${activeTarget.index + 1}/${layout.panes.length}`
            : (layout.sideChat ? t('scope.badge.plusSide') : '')));
      badgeTag.textContent = shortTag;
      badgeTag.hidden = !shortTag;
      if (shortTag) badgeTag.setAttribute('data-scope-locked', isLocked ? 'true' : 'false');
      else badgeTag.removeAttribute?.('data-scope-locked');
    }

    const keyChip = el('key-scope-chip');
    if (keyChip) {
      keyChip.textContent = activeTarget ? getScopeTargetLabel(activeTarget, layout) : '';
      keyChip.hidden = !activeTarget;
      if (activeTarget) keyChip.setAttribute('data-scope-kind', activeTarget.role === 'sidechat' ? 'sidechat' : 'pane');
      else keyChip.removeAttribute?.('data-scope-kind');
    }

    const scopeBar = el('ctx-scope-bar');
    const pillsWrap = el('ctx-scope-pills');
    if (!scopeBar || !pillsWrap) return;
    pillsWrap.replaceChildren();
    scopeBar.hidden = !activeTarget;
    if (!activeTarget) return;

    for (const item of layout.targets) {
      const btn = document.createElement('button');
      const selected = sameRouteId(item.id, activeTarget.id);
      const label = getScopeTargetLabel(item, layout);
      const displayLabel = (item.role === 'sidechat' && item.titleHint && item.titleHint !== label) ? `${label} · ${item.titleHint}` : label;
      btn.type = 'button';
      btn.className = `ctx-scope-pill${selected ? ' is-active' : ''}${item.role === 'sidechat' ? ' is-sidechat' : ''}`;
      btn.setAttribute('role', 'tab');
      btn.setAttribute('aria-selected', selected ? 'true' : 'false');
      btn.setAttribute('data-scope-id', item.id);
      btn.setAttribute('data-scope-role', item.role);
      btn.title = t(item.isFocused ? 'scope.pill.titleFocused' : 'scope.pill.titleOther', { label: displayLabel, id: `${item.id.slice(0, 8)}…` });
      if (item.isFocused || (item.role === 'sidechat' && item.isActiveTab)) {
        const dot = document.createElement('span');
        dot.className = 'ctx-scope-pill-dot';
        dot.setAttribute('aria-hidden', 'true');
        btn.appendChild(dot);
      }
      const txt = document.createElement('span');
      txt.textContent = label;
      btn.appendChild(txt);
      btn.addEventListener('click', () => {
        if (!paneBatch || item.role !== 'pane') return selectConversationScopeView(item.id);
        if (!paneCloseSelection.delete(item.id)) paneCloseSelection.add(item.id);
        syncPaneBatchControls(layout);
        syncPaneHighlights();
      });
      if (item.role === 'pane' && layout.panes.length > 1) {
        const hover = () => { paneHoverId = item.id; syncPaneHighlights(); };
        const leave = () => { if (paneHoverId === item.id) paneHoverId = null; syncPaneHighlights(); };
        btn.addEventListener('pointerenter', hover);
        btn.addEventListener('pointerleave', leave);
        btn.addEventListener('focus', hover);
        btn.addEventListener('blur', leave);
        btn.addEventListener('contextmenu', event => openPaneMenu(event, item));
      }
      pillsWrap.appendChild(btn);
    }

    syncPaneBatchControls(layout);
    const followBtn = el('btn-ctx-scope-follow');
    const followLabel = el('ctx-scope-follow-label');
    if (followBtn && followLabel) {
      followBtn.setAttribute('data-following', isLocked ? 'false' : 'true');
      followLabel.textContent = t(isLocked ? 'scope.follow.locked' : 'scope.follow.auto');
      followBtn.title = isLocked
        ? t('scope.follow.lockedTitle')
        : (layout.focusedIsBlankPane ? t('scope.pill.titleBlankFallback', { label: getScopeTargetLabel(activeTarget, layout) }) : t('scope.follow.title'));
    }
  }
  let activeHeatView = defaultViewPrefs.heatView;
  let heatPageOffset = 0;
  let heatMonthOffset = 0;
  let heatYearOffset = 0;
  let activeCostModel = 'gemini-3.8-flash';
  let activeCostMode = 'ref';
  let autoCheckUpdate = false;
  let allowBetaUpdates = false;
  let cachedLatestRelease = null;

  const METER_RENDERER_VERSION = typeof METER_VERSION !== 'undefined' ? METER_VERSION : '0.9.0-beta.1';
  function formatDisplayVersion(rawVer) {
    const clean = String(rawVer ?? METER_RENDERER_VERSION).replace(/^v/i, '').trim();
    const buildDisplay = typeof METER_DISPLAY_VERSION !== 'undefined' && METER_DISPLAY_VERSION
      ? String(METER_DISPLAY_VERSION).trim()
      : '0.9.0 beta1';
    if (!clean) return buildDisplay;
    const normalizedCurrent = String(METER_RENDERER_VERSION || '').replace(/^v/i, '').trim();
    if (normalizedCurrent && clean === normalizedCurrent) return buildDisplay;
    if (clean === '0.8.8') return '0.8.8 α';
    const betaMatch = clean.match(/^(\d+\.\d+\.\d+)-beta(?:\.(\d+))?$/i);
    if (betaMatch) {
      return `${betaMatch[1]} beta${betaMatch[2] || '1'}`;
    }
    return `v${clean}`;
  }
  const backendStatus = {
    rendererVersion: METER_RENDERER_VERSION,
    backendSource: null,
    backendVersion: null,
    backendPid: null,
    ipcBackendVersion: (typeof window !== 'undefined' && window.__AGContextMeterBootBackend?.backendVersion)
      ? String(window.__AGContextMeterBootBackend.backendVersion)
      : null,
    liveHostVersion: (typeof window !== 'undefined' && window.__AGContextMeterLive?.version)
      ? String(window.__AGContextMeterLive.version)
      : null,
    liveHealthy: null,
    hotReloadFallback: false,
    backendVersionMismatch: false,
    lastVerifiedAtMs: null,
    lastQuotaDurationMs: null,
    lastError: null
  };

  function hasLiveHttpBridge() {
    return typeof window !== 'undefined' && Boolean(window.__AGContextMeterLive?.port && window.__AGContextMeterLive?.token);
  }

  function hasLiveRouteCapability(routePath) {
    if (!hasLiveHttpBridge()) return false;
    const caps = window.__AGContextMeterLive?.capabilities;
    if (!caps || typeof caps !== 'object') return true;
    const map = {
      '/quota': 'quota',
      '/scan': 'scan',
      '/token-history': 'tokenHistory',
      '/record-calls': 'recordCalls',
      '/get-settings': 'settings',
      '/save-settings': 'settings',
      '/launch-cli': 'launchCli',
      '/context-unlock-status': 'contextUnlock',
      '/context-unlock-apply': 'contextUnlock',
      '/context-unlock-restore': 'contextUnlock',
      '/enhance-status': 'enhance',
      '/enhance-apply': 'enhance',
      '/enhance-restore': 'enhance',
      '/restart-language-servers': 'enhance',
      '/rehydrate-status': 'rehydrate',
      '/rehydrate-apply': 'rehydrate',
      '/rehydrate-disable': 'rehydrate',
      '/rehydrate-restore': 'rehydrate',
      '/rehydrate-install-python': 'rehydrate',
      '/modules-status': 'modules',
      '/toggle-module': 'modules',
      '/test-proxy': 'modules',
      '/accounts-overview': 'accounts',
      '/accounts-action': 'accounts',
      '/check-update': 'checkUpdate',
      '/apply-update': 'applyUpdate'
    };
    const key = map[routePath];
    if (!key) return true;
    if (key === 'rehydrate') {
      if (!caps || typeof caps !== 'object') return false;
      return Array.isArray(caps) ? caps.includes('rehydrate') : caps.rehydrate === true;
    }
    if (Array.isArray(caps)) return caps.includes(key);
    return caps[key] !== false;
  }

  function shouldPreferLiveHost(ipcAvailable = false, routePath = '') {
    if (!hasLiveHttpBridge()) return false;
    if (routePath && !hasLiveRouteCapability(routePath)) return false;
    if (!ipcAvailable) return true;
    if (backendStatus.liveHealthy === false) return false;
    const live = window.__AGContextMeterLive || {};
    if (backendStatus.ipcBackendVersion === METER_RENDERER_VERSION) {
      return false;
    }
    if (live.version && live.version === METER_RENDERER_VERSION) {
      return true;
    }
    if (typeof window !== 'undefined' && window.__AGContextMeterHotReloadContext?.preferLiveHost) {
      return true;
    }
    return false;
  }

  async function postLiveHttpEndpoint(routePath, body = {}, opts = {}) {
    const live = typeof window !== 'undefined' ? window.__AGContextMeterLive : null;
    if (!live?.port || !live?.token) {
      throw new Error('LIVE_BRIDGE_UNAVAILABLE');
    }
    const headers = { 'Content-Type': 'application/json', 'X-AG-Context-Token': live.token };
    const fetchOpts = {
      method: 'POST',
      headers,
      body: JSON.stringify(body || {})
    };
    if (opts.signal) fetchOpts.signal = opts.signal;
    const r = await fetch(`http://127.0.0.1:${live.port}${routePath}`, fetchOpts);
    if (!r.ok) {
      const errBody = typeof r.json === 'function' ? await r.json().catch(() => null) : null;
      const err = new Error(errBody?.error || `HTTP ${r.status}`);
      err.httpStatus = r.status;
      err.responseData = errBody;
      throw err;
    }
    return await r.json();
  }

  function syncObservedBackendMeta(source, payloadOrRes, durationMs = null) {
    if (Number.isFinite(durationMs)) backendStatus.lastQuotaDurationMs = durationMs;
    const ver = payloadOrRes?.collectorVersion || payloadOrRes?.backendVersion || payloadOrRes?.version || payloadOrRes?.data?.collectorVersion || payloadOrRes?.data?.backendVersion || null;
    if (source === 'live-host') {
      backendStatus.liveHealthy = true;
      backendStatus.backendSource = 'live-host';
      backendStatus.hotReloadFallback = false;
      if (ver) {
        backendStatus.backendVersion = String(ver);
        backendStatus.liveHostVersion = String(ver);
      } else if (window.__AGContextMeterLive?.version) {
        backendStatus.backendVersion = String(window.__AGContextMeterLive.version);
      }
      if (payloadOrRes?.pid) backendStatus.backendPid = payloadOrRes.pid;
    } else if (source === 'electron-ipc') {
      backendStatus.backendSource = 'electron-ipc';
      if (ver) {
        backendStatus.backendVersion = String(ver);
        backendStatus.ipcBackendVersion = String(ver);
      }
    }
    backendStatus.backendVersionMismatch = Boolean(
      backendStatus.backendVersion &&
      backendStatus.backendVersion !== METER_RENDERER_VERSION
    );
    backendStatus.lastVerifiedAtMs = Date.now();
  }

  async function callBackendWithPriority({ ipcCall = null, liveRoute = '', liveBody = {}, liveFetchOpts = {}, onFallback = null } = {}) {
    const hasIpc = typeof ipcCall === 'function';
    const preferLive = shouldPreferLiveHost(hasIpc, liveRoute);
    if (preferLive && liveRoute) {
      try {
        const res = await postLiveHttpEndpoint(liveRoute, liveBody, liveFetchOpts);
        syncObservedBackendMeta('live-host', res?.data || res);
        return { source: 'live-host', result: res };
      } catch (liveErr) {
        if (liveErr?.name === 'AbortError') throw liveErr;
        backendStatus.liveHealthy = false;
        backendStatus.lastError = liveErr?.message || String(liveErr || '');
        if (!hasIpc) throw liveErr;
        backendStatus.hotReloadFallback = true;
        if (typeof onFallback === 'function') onFallback(liveErr);
      }
    }
    if (hasIpc) {
      const res = await ipcCall();
      syncObservedBackendMeta('electron-ipc', res?.data || res);
      return { source: 'electron-ipc', result: res };
    }
    if (hasLiveHttpBridge() && liveRoute) {
      const res = await postLiveHttpEndpoint(liveRoute, liveBody, liveFetchOpts);
      syncObservedBackendMeta('live-host', res?.data || res);
      return { source: 'live-host', result: res };
    }
    return { source: 'none', result: null };
  }

  /**
   * 获取当前有效设备像素比，用于跨屏混合 DPI 下的物理像素网格对齐
   */
  function getEffectiveDpr() {
    try {
      const dpr = typeof window !== 'undefined' ? Number(window.devicePixelRatio) : 1;
      return Number.isFinite(dpr) && dpr > 0 ? dpr : 1;
    } catch {
      return 1;
    }
  }

  /**
   * 将 CSS 逻辑坐标对齐到最近的物理设备像素边界，防止 100%/175% 混合缩放下出现亚像素偏移发虚
   */
  function snapToDevicePixel(px) {
    const num = Number(px);
    if (!Number.isFinite(num)) return 0;
    const dpr = getEffectiveDpr();
    return Math.round(num * dpr) / dpr;
  }

// =========================================================================
  // 模块 1: 0 级主题跟随、面板与菜单统一背景色、热力图 5 档色阶与自定义颜色选取器
  // =========================================================================
  const COLOR_SLOTS = {
    panelBg: '--ag-custom-panel-bg',
    ringUsed: '--ag-custom-ring-used',
    ringTrack: '--ag-custom-ring-track',
    contextText: '--ag-custom-context-text',
    speedText: '--ag-custom-speed',
    tokenTotal: '--ag-custom-token-total',
    tokenAccent: '--ag-custom-token-accent',
    heatLow: '--ag-custom-heat-low',
    heatHigh: '--ag-custom-heat-high',
    heatLvl0: '--ag-custom-heat-lvl-0',
    heatLvl1: '--ag-custom-heat-lvl-1',
    heatLvl2: '--ag-custom-heat-lvl-2',
    heatLvl3: '--ag-custom-heat-lvl-3',
    heatLvl4: '--ag-custom-heat-lvl-4'
  };
  const COLOR_STORAGE_KEY = 'ag_custom_colors_v1';
  const HEAT_PRESET_STORAGE_KEY = 'ag_heat_preset_v1';
  const customColors = {
    panelBg: '',
    ringUsed: '',
    ringTrack: '',
    contextText: '',
    speedText: '',
    tokenTotal: '',
    tokenAccent: '',
    heatLow: '',
    heatHigh: '',
    heatLvl0: '',
    heatLvl1: '',
    heatLvl2: '',
    heatLvl3: '',
    heatLvl4: ''
  };
  let heatPreset = 'purple';

  const HEAT_PRESETS = {
    purple: {
      dark: ['#27272a', '#3f1e6b', '#652ab7', '#9053f8', '#c084fc'],
      light: ['#e4e4e7', '#e9d5ff', '#c084fc', '#9333ea', '#6b21a8']
    },
    yellow: {
      dark: ['#27272a', '#713f12', '#a16207', '#eab308', '#fde047'],
      light: ['#e4e4e7', '#fef08a', '#facc15', '#ca8a04', '#854d0e']
    },
    green: {
      dark: ['#27272a', '#14532d', '#15803d', '#22c55e', '#86efac'],
      light: ['#e4e4e7', '#bbf7d0', '#4ade80', '#16a34a', '#14532d']
    },
    blue: {
      dark: ['#27272a', '#1e3a8a', '#1d4ed8', '#3b82f6', '#93c5fd'],
      light: ['#e4e4e7', '#bfdbfe', '#60a5fa', '#2563eb', '#1e3a8a']
    },
    red: {
      dark: ['#27272a', '#7f1d1d', '#b91c1c', '#ef4444', '#fca5a5'],
      light: ['#e4e4e7', '#fecaca', '#f87171', '#dc2626', '#7f1d1d']
    }
  };

  try {
    const rawColors = typeof localStorage !== 'undefined' && localStorage.getItem(COLOR_STORAGE_KEY);
    if (rawColors) {
      const parsed = JSON.parse(rawColors);
      for (const k of Object.keys(COLOR_SLOTS)) {
        if (typeof parsed?.[k] === 'string') customColors[k] = parsed[k];
      }
      if (typeof parsed?.heatPreset === 'string' && HEAT_PRESETS[parsed.heatPreset]) {
        heatPreset = parsed.heatPreset;
      }
    }
    const savedPreset = typeof localStorage !== 'undefined' && localStorage.getItem(HEAT_PRESET_STORAGE_KEY);
    if (savedPreset && HEAT_PRESETS[savedPreset]) heatPreset = savedPreset;
  } catch {}

  function saveCustomColors() {
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify({ ...customColors, heatPreset }));
        localStorage.setItem(HEAT_PRESET_STORAGE_KEY, heatPreset);
      }
    } catch {}
  }

  // 色彩空间转换与格式化工具（HEX <-> RGB <-> HSV <-> HSL）
  function clampNum(n, min, max) {
    return Math.min(max, Math.max(min, Number.isFinite(n) ? n : min));
  }

  function rgbToHex(r, g, b) {
    const to2 = v => clampNum(Math.round(v), 0, 255).toString(16).padStart(2, '0');
    return `#${to2(r)}${to2(g)}${to2(b)}`;
  }

  function hexToRgb(hexStr) {
    if (!hexStr || typeof hexStr !== 'string') return null;
    const clean = hexStr.trim().replace(/^#/, '');
    if (!/^[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(clean)) return null;
    const full = clean.length === 3 ? clean.split('').map(c => c + c).join('') : clean;
    const num = parseInt(full, 16);
    if (Number.isNaN(num)) return null;
    return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255 };
  }

  function hslToRgb(h, s, l) {
    const hn = ((Number(h) % 360) + 360) % 360;
    const sn = clampNum(Number(s), 0, 100) / 100;
    const ln = clampNum(Number(l), 0, 100) / 100;
    const c = (1 - Math.abs(2 * ln - 1)) * sn;
    const x = c * (1 - Math.abs(((hn / 60) % 2) - 1));
    const m = ln - c / 2;
    let r1 = 0, g1 = 0, b1 = 0;
    if (hn < 60) { r1 = c; g1 = x; }
    else if (hn < 120) { r1 = x; g1 = c; }
    else if (hn < 180) { g1 = c; b1 = x; }
    else if (hn < 240) { g1 = x; b1 = c; }
    else if (hn < 300) { r1 = x; b1 = c; }
    else { r1 = c; b1 = x; }
    return {
      r: Math.round((r1 + m) * 255),
      g: Math.round((g1 + m) * 255),
      b: Math.round((b1 + m) * 255)
    };
  }

  function splitTopLevelCssArgs(expr) {
    const parts = [];
    let depth = 0;
    let cur = '';
    for (let i = 0; i < expr.length; i++) {
      const ch = expr[i];
      if (ch === '(') depth++;
      else if (ch === ')' && depth > 0) depth--;
      if (ch === ',' && depth === 0) {
        parts.push(cur.trim());
        cur = '';
      } else {
        cur += ch;
      }
    }
    if (cur.trim()) parts.push(cur.trim());
    return parts;
  }

  function evalColorMixSrgb(input) {
    const m = String(input || '').trim().match(/^color-mix\(\s*in\s+srgb\s*,\s*([\s\S]+)\)$/i);
    if (!m) return null;
    const args = splitTopLevelCssArgs(m[1]);
    if (args.length !== 2) return null;
    const parseStop = (part) => {
      const pctMatch = part.match(/\s+([\d.]+)%\s*$/);
      const pct = pctMatch ? Number(pctMatch[1]) : null;
      const colorExpr = pctMatch ? part.slice(0, pctMatch.index).trim() : part.trim();
      const hex = normalizeHex(colorExpr);
      const rgb = hex ? hexToRgb(hex) : null;
      return rgb ? { rgb, pct } : null;
    };
    const s1 = parseStop(args[0]);
    const s2 = parseStop(args[1]);
    if (!s1 || !s2) return null;
    let w1 = s1.pct;
    let w2 = s2.pct;
    if (w1 == null && w2 == null) { w1 = 50; w2 = 50; }
    else if (w1 != null && w2 == null) { w2 = 100 - w1; }
    else if (w1 == null && w2 != null) { w1 = 100 - w2; }
    const sum = w1 + w2;
    if (!Number.isFinite(sum) || sum <= 0) return null;
    const p1 = w1 / sum;
    const p2 = w2 / sum;
    return rgbToHex(
      s1.rgb.r * p1 + s2.rgb.r * p2,
      s1.rgb.g * p1 + s2.rgb.g * p2,
      s1.rgb.b * p1 + s2.rgb.b * p2
    );
  }

  function normalizeHex(input) {
    if (!input || typeof input !== 'string') return null;
    const s = input.trim();
    if (!s || /^transparent$/i.test(s)) return null;
    const direct = hexToRgb(s);
    if (direct) return rgbToHex(direct.r, direct.g, direct.b);
    if (/^color-mix\(/i.test(s)) {
      const mixed = evalColorMixSrgb(s);
      if (mixed) return mixed;
    }
    const mColorSrgb = s.match(/^color\(\s*srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)(?:\s*\/\s*([\d.]+%?))?\s*\)$/i);
    if (mColorSrgb) {
      if (mColorSrgb[4] !== undefined) {
        const alphaRaw = mColorSrgb[4].endsWith('%') ? Number(mColorSrgb[4].slice(0, -1)) / 100 : Number(mColorSrgb[4]);
        if (!Number.isNaN(alphaRaw) && alphaRaw <= 0.01) return null;
      }
      return rgbToHex(Number(mColorSrgb[1]) * 255, Number(mColorSrgb[2]) * 255, Number(mColorSrgb[3]) * 255);
    }
    const mRgb = s.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*[,/]\s*([\d.]+%?))?/i);
    if (mRgb) {
      if (mRgb[4] !== undefined) {
        const alphaRaw = mRgb[4].endsWith('%') ? Number(mRgb[4].slice(0, -1)) / 100 : Number(mRgb[4]);
        if (!Number.isNaN(alphaRaw) && alphaRaw <= 0.01) return null;
      }
      return rgbToHex(Number(mRgb[1]), Number(mRgb[2]), Number(mRgb[3]));
    }
    const mHsl = s.match(/hsla?\(\s*([\d.]+)\s*,\s*([\d.]+)%?\s*,\s*([\d.]+)%?(?:\s*[,/]\s*([\d.]+%?))?/i);
    if (mHsl) {
      if (mHsl[4] !== undefined) {
        const alphaRaw = mHsl[4].endsWith('%') ? Number(mHsl[4].slice(0, -1)) / 100 : Number(mHsl[4]);
        if (!Number.isNaN(alphaRaw) && alphaRaw <= 0.01) return null;
      }
      const rgb = hslToRgb(Number(mHsl[1]), Number(mHsl[2]), Number(mHsl[3]));
      return rgbToHex(rgb.r, rgb.g, rgb.b);
    }
    return null;
  }

  function rgbToHsv(r, g, b) {
    const rn = r / 255, gn = g / 255, bn = b / 255;
    const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
    const d = max - min;
    let h = 0;
    if (d !== 0) {
      if (max === rn) h = ((gn - bn) / d + (gn < bn ? 6 : 0)) * 60;
      else if (max === gn) h = ((bn - rn) / d + 2) * 60;
      else h = ((rn - gn) / d + 4) * 60;
    }
    const s = max === 0 ? 0 : (d / max) * 100;
    const v = max * 100;
    return { h: Math.round(h), s: Math.round(s), v: Math.round(v) };
  }

  function hsvToRgb(h, s, v) {
    const hn = ((Number(h) % 360) + 360) % 360;
    const sn = clampNum(Number(s), 0, 100) / 100;
    const vn = clampNum(Number(v), 0, 100) / 100;
    const c = vn * sn;
    const x = c * (1 - Math.abs(((hn / 60) % 2) - 1));
    const m = vn - c;
    let r1 = 0, g1 = 0, b1 = 0;
    if (hn < 60) { r1 = c; g1 = x; }
    else if (hn < 120) { r1 = x; g1 = c; }
    else if (hn < 180) { g1 = c; b1 = x; }
    else if (hn < 240) { g1 = x; b1 = c; }
    else if (hn < 300) { r1 = x; b1 = c; }
    else { r1 = c; b1 = x; }
    return {
      r: Math.round((r1 + m) * 255),
      g: Math.round((g1 + m) * 255),
      b: Math.round((b1 + m) * 255)
    };
  }

  function rgbToHsl(r, g, b) {
    const rn = r / 255, gn = g / 255, bn = b / 255;
    const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
    const l = (max + min) / 2;
    const d = max - min;
    let h = 0, s = 0;
    if (d !== 0) {
      s = d / (1 - Math.abs(2 * l - 1));
      if (max === rn) h = ((gn - bn) / d + (gn < bn ? 6 : 0)) * 60;
      else if (max === gn) h = ((bn - rn) / d + 2) * 60;
      else h = ((rn - gn) / d + 4) * 60;
    }
    return { h: Math.round(h), s: Math.round(s * 100), l: Math.round(l * 100) };
  }

  function interpolateHex(hexA, hexB, t) {
    const a = hexToRgb(hexA) || { r: 39, g: 39, b: 42 };
    const b = hexToRgb(hexB) || { r: 192, g: 132, b: 252 };
    const ratio = clampNum(t, 0, 1);
    return rgbToHex(
      a.r + (b.r - a.r) * ratio,
      a.g + (b.g - a.g) * ratio,
      a.b + (b.b - a.b) * ratio
    );
  }

  let currentThemeMode = 'auto';
  try {
    currentThemeMode = (typeof localStorage !== 'undefined' && localStorage.getItem('ag_theme_mode')) || 'auto';
  } catch {}

  function parseRgbLuminance(colorStr) {
    if (!colorStr || typeof colorStr !== 'string') return null;
    const rgb = hexToRgb(normalizeHex(colorStr));
    if (rgb) return (0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b) / 255;
    return null;
  }

  function getHostZeroLevelBg(isLight) {
    const fallback = isLight ? '#ffffff' : '#181818';
    try {
      if (typeof window !== 'undefined' && typeof window.getComputedStyle === 'function') {
        const rootEl = document.body || document.documentElement;
        if (rootEl) {
          const cs = window.getComputedStyle(rootEl);
          const candidates = [
            cs.getPropertyValue('--background')?.trim(),
            cs.backgroundColor?.trim()
          ].filter(Boolean);
          for (const raw of candidates) {
            const norm = normalizeHex(raw);
            if (!norm) continue;
            const lum = parseRgbLuminance(norm);
            const normIsLight = lum != null ? lum > 0.55 : Boolean(isLight);
            if (normIsLight === Boolean(isLight)) return norm;
            return fallback;
          }
        }
      }
    } catch {}
    return fallback;
  }

  function getSystemTheme() {
    try {
      const body = document.body;
      const doc = document.documentElement;
      if (body?.classList?.contains('theme-light') || body?.classList?.contains('light') || doc?.classList?.contains('light') || body?.classList?.contains('vscode-light')) return 'light';
      if (body?.classList?.contains('theme-dark') || body?.classList?.contains('dark') || doc?.classList?.contains('dark') || body?.classList?.contains('vscode-dark')) return 'dark';
      if (doc?.style?.colorScheme === 'light') return 'light';
      if (doc?.style?.colorScheme === 'dark') return 'dark';
      if (typeof window !== 'undefined' && typeof window.getComputedStyle === 'function' && (body || doc)) {
        const cs = window.getComputedStyle(body || doc);
        const bgVar = cs.getPropertyValue('--background') || cs.backgroundColor;
        const lum = parseRgbLuminance(bgVar);
        if (lum != null) return lum > 0.55 ? 'light' : 'dark';
      }
      if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
        if (window.matchMedia('(prefers-color-scheme: light)').matches) return 'light';
      }
    } catch {}
    return 'dark';
  }

  function resolveTheme() {
    if (currentThemeMode === 'light') return 'light';
    if (currentThemeMode === 'dark') return 'dark';
    return getSystemTheme();
  }

  function getPresetHeatmapScale() {
    const isLight = resolveTheme() === 'light';
    const presetObj = HEAT_PRESETS[heatPreset] || HEAT_PRESETS.purple;
    return (isLight ? presetObj.light : presetObj.dark).slice();
  }

  function getBaseHeatmapScale() {
    const base = getPresetHeatmapScale();
    const lowCustom = normalizeHex(customColors.heatLow);
    const highCustom = normalizeHex(customColors.heatHigh);
    if (lowCustom || highCustom) {
      const c0 = lowCustom || base[0];
      const c4 = highCustom || base[4];
      return [
        c0,
        interpolateHex(c0, c4, 0.25),
        interpolateHex(c0, c4, 0.5),
        interpolateHex(c0, c4, 0.75),
        c4
      ];
    }
    return base;
  }

  function getEffectiveHeatmapScale() {
    const scale = getBaseHeatmapScale();
    for (let i = 0; i < 5; i++) {
      const lvlCustom = normalizeHex(customColors[`heatLvl${i}`]);
      if (lvlCustom) scale[i] = lvlCustom;
    }
    return scale;
  }

  function getDefaultSlotColor(slotKey) {
    const isLight = resolveTheme() === 'light';
    const presetScale = getPresetHeatmapScale();
    const baseScale = getBaseHeatmapScale();
    switch (slotKey) {
      case 'panelBg': return getHostZeroLevelBg(isLight);
      case 'ringUsed': return isLight ? '#18181b' : '#e6e6eb';
      case 'ringTrack': return isLight ? '#b8b8c2' : '#52525b';
      case 'contextText': return isLight ? '#18181b' : '#ececef';
      case 'speedText': return isLight ? '#0284c7' : '#38bdf8';
      case 'tokenTotal': return isLight ? '#7c3aed' : '#c084fc';
      case 'tokenAccent': return isLight ? '#7c3aed' : '#a78bfa';
      case 'heatLow': return presetScale[0];
      case 'heatHigh': return presetScale[4];
      case 'heatLvl0': return baseScale[0];
      case 'heatLvl1': return baseScale[1];
      case 'heatLvl2': return baseScale[2];
      case 'heatLvl3': return baseScale[3];
      case 'heatLvl4': return baseScale[4];
      default: return '#7748cf';
    }
  }

  function getEffectiveSlotColor(slotKey) {
    return normalizeHex(customColors[slotKey]) || getDefaultSlotColor(slotKey);
  }

  function applyHeatmapPalette() {
    const scale = getEffectiveHeatmapScale();
    for (let i = 0; i < 5; i++) {
      host.style.setProperty(`--ag-heat-lvl-${i}`, scale[i]);
      const legEl = el(`heat-leg-${i}`);
      if (legEl) {
        legEl.style.background = scale[i];
        legEl.style.setProperty('--swatch-color', scale[i]);
        legEl.setAttribute('data-custom', String(Boolean(customColors[`heatLvl${i}`])));
      }
    }
    const hasCustomHeat = Boolean(
      customColors.heatLow || customColors.heatHigh ||
      customColors.heatLvl0 || customColors.heatLvl1 || customColors.heatLvl2 || customColors.heatLvl3 || customColors.heatLvl4
    );
    try {
      const group = el('heat-preset-group');
      if (group?.querySelectorAll) {
        const btns = group.querySelectorAll('[data-heat-preset]');
        for (const btn of btns) {
          const pName = btn.getAttribute('data-heat-preset');
          btn.setAttribute('data-active', String(!hasCustomHeat && pName === heatPreset));
        }
      }
    } catch {}
  }

  function syncSwatchAndResetButtons() {
    for (const key of Object.keys(COLOR_SLOTS)) {
      const val = customColors[key];
      const eff = getEffectiveSlotColor(key);
      const inputEl = el(`color-${key}`);
      if (inputEl) inputEl.value = eff;
      const swatchEl = el(`swatch-${key}`);
      if (swatchEl) {
        swatchEl.style.setProperty('--swatch-color', eff);
        swatchEl.style.background = eff;
      }
      const resetBtn = el(`reset-${key}`);
      if (resetBtn) {
        resetBtn.setAttribute('data-mode', val ? 'custom' : 'auto');
        if (key.startsWith('heatLvl')) {
          resetBtn.textContent = val ? t('colors.btn.restore') : t('colors.btn.preset');
        } else if (key === 'heatLow' || key === 'heatHigh') {
          resetBtn.textContent = val ? t('colors.btn.restorePreset') : t('colors.btn.preset');
        } else {
          resetBtn.textContent = val ? t('colors.btn.restoreDefault') : t('cp.followTheme');
        }
      }
    }
    const resetHeatLvlsBtn = el('reset-heat-lvls');
    if (resetHeatLvlsBtn) {
      const anyHeatLvl = Boolean(
        customColors.heatLvl0 || customColors.heatLvl1 || customColors.heatLvl2 || customColors.heatLvl3 || customColors.heatLvl4 ||
        customColors.heatLow || customColors.heatHigh
      );
      resetHeatLvlsBtn.setAttribute('data-mode', anyHeatLvl ? 'custom' : 'auto');
    }
    // 面板 A 中的镜像色块按钮同步
    const mirrorMap = {
      'swatch-panelBg-tokens': 'panelBg',
      'swatch-tokenTotal-tokens': 'tokenTotal',
      'swatch-tokenAccent-tokens': 'tokenAccent'
    };
    for (const [id, slot] of Object.entries(mirrorMap)) {
      const sw = el(id);
      if (sw) {
        const eff = getEffectiveSlotColor(slot);
        sw.style.setProperty('--swatch-color', eff);
        sw.style.background = eff;
      }
    }
    const resetBgTokens = el('reset-panelBg-tokens');
    if (resetBgTokens) {
      const hasBg = Boolean(customColors.panelBg);
      resetBgTokens.setAttribute('data-mode', hasBg ? 'custom' : 'auto');
      resetBgTokens.textContent = hasBg ? t('colors.btn.restoreDefault') : t('cp.followTheme');
    }
  }

  function getContinuousScaleStops() {
    const scale = getEffectiveHeatmapScale();
    const isLight = resolveTheme() === 'light';
    const hasCustomHeat = Boolean(
      customColors.heatLow ||
      customColors.heatHigh ||
      customColors.heatLvl1 ||
      customColors.heatLvl2 ||
      customColors.heatLvl3 ||
      customColors.heatLvl4
    );
    if (!isLight && heatPreset === 'purple' && !hasCustomHeat) {
      return ['#2E1A47', '#6D28D9', '#9333EA', '#D8B4FE'];
    }
    return [scale[1], scale[2], scale[3], scale[4]].filter(Boolean);
  }

  function getContinuousHeatColor(value, modeOrAnchor = 'heat') {
    const v = Number(value) || 0;
    if (v <= 0) return null;
    const core = globalThis.__AGContextMeterCore || {};
    let resp = 0;
    if (typeof modeOrAnchor === 'string') {
      resp = typeof core.computeColorScaleResponse === 'function'
        ? core.computeColorScaleResponse(v, modeOrAnchor)
        : (typeof core.computeMixedScaleResponse === 'function' ? core.computeMixedScaleResponse(v, 100e6) : 0.5);
    } else {
      const anchor = Number(modeOrAnchor) || 100e6;
      resp = typeof core.computeMixedScaleResponse === 'function'
        ? core.computeMixedScaleResponse(v, anchor)
        : Math.max(0, Math.min(1, Math.pow(Math.min(v, anchor) / anchor, 0.42)));
    }
    const stops = getContinuousScaleStops();
    if (typeof core.interpolateScaleColorHsl === 'function') {
      return core.interpolateScaleColorHsl(resp, stops);
    }
    return stops[stops.length - 1] || '#9333ea';
  }

  let __chartsReady = false;

  function refreshActiveChartViews() {
    if (!__chartsReady) return;
    if (activeHeatView === 'daily' && typeof renderHeatmapGrid === 'function') renderHeatmapGrid(true);
    else if (activeHeatView === 'weekly' && typeof renderHeatmapWeekly === 'function') renderHeatmapWeekly();
    else if (activeHeatView === 'monthly' && typeof renderHeatmapMonthly === 'function') renderHeatmapMonthly();
    else if (activeHeatView === 'yearly' && typeof renderHeatmapYearly === 'function') renderHeatmapYearly();
    else if (activeHeatView === 'cum' && typeof renderHeatmapCum === 'function') renderHeatmapCum();
    const modelViewEl = el('model-usage-view');
    if (modelViewEl && modelViewEl.style && modelViewEl.style.display === 'block' && typeof renderModelUsageView === 'function') {
      renderModelUsageView();
    }
  }

  function applyCustomColors() {
    for (const [key, cssVar] of Object.entries(COLOR_SLOTS)) {
      const val = customColors[key];
      if (val) {
        host.style.setProperty(cssVar, val);
      } else if (host.style.removeProperty) {
        host.style.removeProperty(cssVar);
      } else {
        host.style.setProperty(cssVar, '');
      }
    }
    if (customColors.panelBg) {
      const lum = parseRgbLuminance(customColors.panelBg);
      if (lum != null) {
        host.setAttribute('data-panel-tone', lum > 0.55 ? 'light' : 'dark');
      }
    } else {
      host.removeAttribute('data-panel-tone');
    }
    applyHeatmapPalette();
    syncSwatchAndResetButtons();
    refreshActiveChartViews();
  }

  function setCustomColor(key, value) {
    if (!Object.prototype.hasOwnProperty.call(COLOR_SLOTS, key)) return;
    const raw = value ? String(value).trim() : '';
    const norm = raw ? (normalizeHex(raw) || raw) : '';
    customColors[key] = norm;
    if (key === 'heatLow' && norm) customColors.heatLvl0 = '';
    if (key === 'heatHigh' && norm) customColors.heatLvl4 = '';
    saveCustomColors();
    applyCustomColors();
  }

  function setHeatPreset(presetName) {
    if (!HEAT_PRESETS[presetName]) return;
    heatPreset = presetName;
    customColors.heatLow = '';
    customColors.heatHigh = '';
    for (let i = 0; i < 5; i++) {
      customColors[`heatLvl${i}`] = '';
    }
    saveCustomColors();
    applyCustomColors();
  }

  function resetHeatmapLevels() {
    customColors.heatLow = '';
    customColors.heatHigh = '';
    for (let i = 0; i < 5; i++) {
      customColors[`heatLvl${i}`] = '';
    }
    saveCustomColors();
    applyCustomColors();
  }

  function resetCustomColors() {
    for (const key of Object.keys(COLOR_SLOTS)) customColors[key] = '';
    heatPreset = 'purple';
    saveCustomColors();
    applyCustomColors();
  }

  function applyTheme() {
    const activeTheme = resolveTheme();
    host.setAttribute('data-theme', activeTheme);
    const hostBg = getHostZeroLevelBg(activeTheme === 'light');
    host.style.setProperty('--ag-host-bg', hostBg);
    const btns = [el('theme-toggle'), el('theme-toggle-tokens')].filter(Boolean);
    btns.forEach(btn => {
      if (currentThemeMode === 'auto') {
        btn.textContent = activeTheme === 'light' ? '🌗' : '🌓';
        btn.title = t('theme.autoTitle', { mode: activeTheme === 'light' ? t('theme.light') : t('theme.dark') });
      } else if (currentThemeMode === 'light') {
        btn.textContent = '☀️';
        btn.title = t('theme.lightTitle');
      } else {
        btn.textContent = '🌙';
        btn.title = t('theme.darkTitle');
      }
    });
    applyHeatmapPalette();
    syncSwatchAndResetButtons();
    refreshActiveChartViews();
    syncNativeOverlayTheme();
  }

  let lastSyncedOverlayKey = '';
  let overlayColorProbeEl = null;
  function resolveCssColorToHex(cssExpr, prop = 'color') {
    if (!cssExpr || typeof cssExpr !== 'string') return '';
    const trimmed = cssExpr.trim();
    if (!trimmed || trimmed === 'transparent' || trimmed === 'rgba(0, 0, 0, 0)') return '';
    const direct = normalizeHex(trimmed);
    if (direct) return direct;
    try {
      if (typeof document === 'undefined' || !document.body || typeof window?.getComputedStyle !== 'function') return '';
      if (!overlayColorProbeEl) {
        overlayColorProbeEl = document.createElement('div');
        if (overlayColorProbeEl.style) {
          overlayColorProbeEl.style.cssText = 'position:fixed;width:0;height:0;overflow:hidden;opacity:0;pointer-events:none;z-index:-1;';
        }
        overlayColorProbeEl.setAttribute?.('aria-hidden', 'true');
      }
      if (!overlayColorProbeEl.isConnected && typeof document.body.appendChild === 'function') {
        document.body.appendChild(overlayColorProbeEl);
      }
      if (!overlayColorProbeEl.style) return '';
      overlayColorProbeEl.style[prop] = '';
      overlayColorProbeEl.style[prop] = trimmed;
      const computed = window.getComputedStyle(overlayColorProbeEl)?.[prop] || '';
      return normalizeHex(computed) || '';
    } catch {
      return '';
    }
  }

  function resolveNativeTitlebarOverlayColors() {
    const pickHex = (candidates, prop = 'color') => {
      for (const raw of candidates) {
        if (!raw || typeof raw !== 'string') continue;
        const tVal = raw.trim();
        if (!tVal || tVal === 'transparent' || tVal === 'rgba(0, 0, 0, 0)') continue;
        const hex = normalizeHex(tVal) || resolveCssColorToHex(tVal, prop);
        if (hex) return hex;
      }
      return '';
    };
    // 严格读取宿主系统主题判断深浅色兜底值，避免插件自身切换主题时污染原生窗口控制按钮
    const hostIsLight = getSystemTheme() === 'light';
    try {
      const nativeStyle = typeof getComputedStyle === 'function' ? getComputedStyle(document.documentElement) : null;
      const bodyStyle = typeof getComputedStyle === 'function' && document.body ? getComputedStyle(document.body) : null;
      const menuBarNode = typeof document.querySelector === 'function'
        ? document.querySelector('[data-testid="title-menu-bar"]')
        : null;
      const menuBarStyle = menuBarNode && typeof getComputedStyle === 'function' ? getComputedStyle(menuBarNode) : null;
      const barNode = typeof document.querySelector === 'function'
        ? (document.querySelector('[class*="@container/titlebar"]') || document.querySelector('header, nav, .titlebar'))
        : null;
      const barStyle = barNode && typeof getComputedStyle === 'function' ? getComputedStyle(barNode) : null;
      const sidebarVarRaw = nativeStyle?.getPropertyValue?.('--sidebar') || '';
      const secFgVarRaw = nativeStyle?.getPropertyValue?.('--secondary-foreground') || '';
      const bg = pickHex([
        menuBarStyle?.backgroundColor,
        nativeStyle?.getPropertyValue?.('--vscode-titleBar-activeBackground'),
        sidebarVarRaw,
        sidebarVarRaw ? 'var(--sidebar)' : '',
        barStyle?.backgroundColor,
        nativeStyle?.getPropertyValue?.('--background'),
        bodyStyle?.backgroundColor
      ], 'backgroundColor') || (hostIsLight ? '#fafafa' : '#131313');
      const fg = pickHex([
        nativeStyle?.getPropertyValue?.('--vscode-titleBar-activeForeground'),
        secFgVarRaw,
        secFgVarRaw ? 'var(--secondary-foreground)' : '',
        menuBarStyle?.color,
        barStyle?.color,
        nativeStyle?.getPropertyValue?.('--foreground'),
        bodyStyle?.color
      ], 'color') || (hostIsLight ? '#383a42' : '#fafafa');
      return { bg, fg };
    } catch {
      return { bg: hostIsLight ? '#fafafa' : '#131313', fg: hostIsLight ? '#383a42' : '#fafafa' };
    }
  }

  function syncNativeOverlayTheme() {
    try {
      if (typeof window === 'undefined') return;
      const { bg, fg } = resolveNativeTitlebarOverlayColors();
      if (!/^#[0-9a-f]{6}$/i.test(bg) || !/^#[0-9a-f]{6}$/i.test(fg)) return;
      const overlayKey = `${bg}|${fg}|30`;
      if (overlayKey === lastSyncedOverlayKey) return;
      lastSyncedOverlayKey = overlayKey;
      if (typeof window.contextMeterAPI?.syncOverlay === 'function') {
        void window.contextMeterAPI.syncOverlay({ color: bg, symbolColor: fg, height: 30, heightCssPx: 30 });
      } else if (typeof window.electronNative?.setTitleBarOverlay === 'function') {
        void window.electronNative.setTitleBarOverlay({ color: bg, symbolColor: fg, height: 30 });
      }
    } catch {}
  }

  function cycleTheme() {
    if (currentThemeMode === 'auto') currentThemeMode = 'light';
    else if (currentThemeMode === 'light') currentThemeMode = 'dark';
    else currentThemeMode = 'auto';
    try {
      if (typeof localStorage !== 'undefined') localStorage.setItem('ag_theme_mode', currentThemeMode);
    } catch {}
    applyTheme();
  }

  let themeObserver = null;
  let overlayMediaCleanup = null;
  const overlaySyncTimers = [];
  try {
    if (typeof MutationObserver !== 'undefined' && document.body) {
      themeObserver = new MutationObserver(() => {
        if (currentThemeMode === 'auto') applyTheme();
        else syncNativeOverlayTheme();
      });
      themeObserver.observe(document.body, { attributes: true, attributeFilter: ['class', 'style', 'data-theme'] });
      if (document.documentElement) {
        themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ['class', 'style', 'data-theme'] });
      }
    }
    if (typeof window !== 'undefined' && typeof window.matchMedia === 'function') {
      const mqlDark = window.matchMedia('(prefers-color-scheme: dark)');
      const onSchemeChange = () => {
        if (state.disposed) return;
        if (currentThemeMode === 'auto') applyTheme();
        else syncNativeOverlayTheme();
      };
      if (typeof mqlDark?.addEventListener === 'function') {
        mqlDark.addEventListener('change', onSchemeChange);
        overlayMediaCleanup = () => { try { mqlDark.removeEventListener('change', onSchemeChange); } catch {} };
      } else if (typeof mqlDark?.addListener === 'function') {
        mqlDark.addListener(onSchemeChange);
        overlayMediaCleanup = () => { try { mqlDark.removeListener(onSchemeChange); } catch {} };
      }
    }
    for (const delayMs of [80, 600, 1800]) {
      const tid = setTimeout(() => {
        if (!state.disposed) syncNativeOverlayTheme();
      }, delayMs);
      overlaySyncTimers.push(tid);
    }
    if (typeof activeDisposers?.add === 'function') {
      activeDisposers.add(() => {
        for (const tid of overlaySyncTimers) clearTimeout(tid);
        overlaySyncTimers.length = 0;
        if (overlayMediaCleanup) { overlayMediaCleanup(); overlayMediaCleanup = null; }
        try { overlayColorProbeEl?.remove?.(); } catch {}
        overlayColorProbeEl = null;
      });
    }
  } catch {}

  applyTheme();
  applyCustomColors();

  // =========================================================================
  // 自定义「颜色选取器」面板交互逻辑（吸管 + 预设圆点 + SV主色区 + 色相条 + HEX/RGB/HSL）
  // =========================================================================
  let activePickerSlot = null;
  let activePickerAnchor = null;
  let cpHsv = { h: 265, s: 77, v: 72 };

  function syncPickerUiFromHsv(skipInputId = '', exactRgb = null) {
    const rgb = exactRgb || hsvToRgb(cpHsv.h, cpHsv.s, cpHsv.v);
    const hex = rgbToHex(rgb.r, rgb.g, rgb.b);
    const hsl = rgbToHsl(rgb.r, rgb.g, rgb.b);

    const svArea = el('cp-sv-area');
    const svThumb = el('cp-sv-thumb');
    const hueThumb = el('cp-hue-thumb');
    const sidePreview = el('cp-side-preview');
    if (svArea) svArea.style.backgroundColor = `hsl(${cpHsv.h}, 100%, 50%)`;
    if (svThumb) {
      svThumb.style.left = `${cpHsv.s}%`;
      svThumb.style.top = `${100 - cpHsv.v}%`;
    }
    if (hueThumb) {
      hueThumb.style.left = `${(cpHsv.h / 360) * 100}%`;
    }
    if (sidePreview) {
      sidePreview.style.background = hex;
    }

    const inHex = el('cp-input-hex');
    const inRgb = el('cp-input-rgb');
    const inHsl = el('cp-input-hsl');
    if (inHex && skipInputId !== 'cp-input-hex') inHex.value = hex;
    if (inRgb && skipInputId !== 'cp-input-rgb') inRgb.value = `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
    if (inHsl && skipInputId !== 'cp-input-hsl') inHsl.value = `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`;
    return hex;
  }

  function applyPickerHex(hexStr, skipInputId = '') {
    const norm = normalizeHex(hexStr);
    if (!norm) return false;
    const rgb = hexToRgb(norm);
    if (!rgb) return false;
    cpHsv = rgbToHsv(rgb.r, rgb.g, rgb.b);
    const appliedHex = syncPickerUiFromHsv(skipInputId, rgb);
    if (activePickerSlot) {
      setCustomColor(activePickerSlot, appliedHex);
    }
    return true;
  }

  let pickerOpVersion = 0;

  function positionColorPickerPopover() {
    const pop = el('color-picker-popover');
    if (!pop || pop.hidden) return;
    try {
      const vw = (typeof window !== 'undefined' && window.innerWidth) || 1280;
      const vh = (typeof window !== 'undefined' && window.innerHeight) || 800;
      const popW = 304;
      const popH = pop.offsetHeight > 0 ? pop.offsetHeight : 340;
      let minLeft = 12;
      if (typeof document.querySelector === 'function') {
        const navEl = document.querySelector('div[role="navigation"]');
        if (navEl?.getBoundingClientRect) {
          const nr = navEl.getBoundingClientRect();
          if (nr.width > 0 && nr.left <= 8 && nr.right < vw - 320) {
            minLeft = Math.ceil(nr.right + 12);
          }
        }
      }
      const snapPx = typeof snapToDevicePixel === 'function' ? snapToDevicePixel : Math.round;
      let left = snapPx((vw - popW) / 2);
      let top = 90;
      if (activePickerAnchor?.getBoundingClientRect) {
        const ar = activePickerAnchor.getBoundingClientRect();
        if (ar.width > 0 || ar.height > 0) {
          left = snapPx(ar.right - popW);
          top = snapPx(ar.bottom + 6);
          if (top + popH > vh - 12 && ar.top > popH + 12) {
            top = snapPx(ar.top - popH - 6);
          }
        }
      }
      left = snapPx(Math.max(minLeft, Math.min(vw - popW - 12, left)));
      top = snapPx(Math.max(42, Math.min(vh - popH - 12, top)));
      pop.style.left = `${left}px`;
      pop.style.top = `${top}px`;
    } catch {}
  }

  function openColorPicker(slotKey, anchorEl = null, labelText = '') {
    if (!Object.prototype.hasOwnProperty.call(COLOR_SLOTS, slotKey)) return;
    const pop = el('color-picker-popover');
    if (!pop) return;

    const op = ++pickerOpVersion;
    activePickerSlot = slotKey;
    activePickerAnchor = anchorEl;

    const lbl = el('cp-target-name');
    if (lbl) lbl.textContent = labelText ? `· ${labelText}` : `· ${slotKey}`;
    const cpResetBtn = el('cp-reset-slot');
    if (cpResetBtn) {
      cpResetBtn.textContent = slotKey.startsWith('heat') ? t('colors.resetLevel') : t('colors.followTheme');
    }
    const startHex = getEffectiveSlotColor(slotKey);
    const rgb = hexToRgb(startHex) || { r: 101, g: 42, b: 183 };
    cpHsv = rgbToHsv(rgb.r, rgb.g, rgb.b);
    syncPickerUiFromHsv();

    pop.setAttribute?.('data-closing', 'false');
    pop.classList?.remove?.('is-closing');
    pop.classList?.add?.('is-opening');
    pop.hidden = false;
    positionColorPickerPopover();

    if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(() => {
        if (pickerOpVersion === op) {
          pop.classList?.remove?.('is-opening');
        }
      });
    } else {
      pop.classList?.remove?.('is-opening');
    }
  }

  function closeColorPicker(immediate = false) {
    const pop = el('color-picker-popover');
    const isMock = !pop?.classList || typeof pop.classList.add !== 'function' || typeof pop.animate !== 'function';
    const isClosing = pop?.classList ? pop.classList.contains('is-closing') : pop?.getAttribute('data-closing') === 'true';
    if (!pop || pop.hidden || isClosing) {
      activePickerSlot = null;
      activePickerAnchor = null;
      return;
    }
    const op = ++pickerOpVersion;
    activePickerSlot = null;
    activePickerAnchor = null;

    const isImmediate = typeof immediate === 'boolean' ? immediate : false;
    if (isImmediate || isMock || (typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches)) {
      pop.setAttribute?.('data-closing', 'false');
      pop.classList?.remove?.('is-opening', 'is-closing');
      pop.hidden = true;
      return;
    }

    pop.setAttribute?.('data-closing', 'true');
    pop.classList?.add?.('is-closing');
    setTimeout(() => {
      if (pickerOpVersion === op) {
        pop.setAttribute?.('data-closing', 'false');
        pop.classList?.remove?.('is-opening', 'is-closing');
        pop.hidden = true;
      }
    }, 130);
  }

  const getHeatLvlLabel = (idx) => t(`colors.lvl${idx}`);

  // 绑定所有颜色色块与恢复按钮事件
  for (const key of Object.keys(COLOR_SLOTS)) {
    const inputEl = el(`color-${key}`);
    const resetBtn = el(`reset-${key}`);
    const swatchBtn = el(`swatch-${key}`);
    inputEl?.addEventListener('input', e => setCustomColor(key, e.target?.value || ''));
    inputEl?.addEventListener('change', e => setCustomColor(key, e.target?.value || ''));
    resetBtn?.addEventListener('click', () => {
      setCustomColor(key, '');
      if (activePickerSlot === key) {
        const eff = getEffectiveSlotColor(key);
        const rgb = hexToRgb(eff) || { r: 101, g: 42, b: 183 };
        cpHsv = rgbToHsv(rgb.r, rgb.g, rgb.b);
        syncPickerUiFromHsv();
      }
    });
    swatchBtn?.addEventListener('click', e => {
      e?.stopPropagation?.();
      openColorPicker(key, swatchBtn, swatchBtn.getAttribute('data-color-label') || key);
    });
  }

  // 热力图右下角「少 ▢▢▢▢▢ 多」5 个小色块图例直接点击弹出颜色选取器单独调色
  for (let i = 0; i < 5; i++) {
    const legBtn = el(`heat-leg-${i}`);
    const slotKey = `heatLvl${i}`;
    legBtn?.addEventListener('click', e => {
      e?.stopPropagation?.();
      toggleTokenColorsDrawer(true);
      const swatchBtn = el(`swatch-${slotKey}`) || legBtn;
      openColorPicker(slotKey, swatchBtn, getHeatLvlLabel(i));
    });
  }
  el('reset-heat-lvls')?.addEventListener('click', () => {
    resetHeatmapLevels();
    if (activePickerSlot?.startsWith('heat')) {
      const eff = getEffectiveSlotColor(activePickerSlot);
      const rgb = hexToRgb(eff) || { r: 101, g: 42, b: 183 };
      cpHsv = rgbToHsv(rgb.r, rgb.g, rgb.b);
      syncPickerUiFromHsv();
    }
  });

  // 面板 A 镜像色块与预设按钮事件
  ['swatch-panelBg-tokens', 'swatch-tokenTotal-tokens', 'swatch-tokenAccent-tokens'].forEach(id => {
    const btn = el(id);
    btn?.addEventListener('click', e => {
      e?.stopPropagation?.();
      const slot = btn.getAttribute('data-color-slot');
      if (slot) openColorPicker(slot, btn, btn.getAttribute('data-color-label') || slot);
    });
  });
  el('reset-panelBg-tokens')?.addEventListener('click', () => setCustomColor('panelBg', ''));
  el('reset-all-colors')?.addEventListener('click', () => { resetCustomColors(); closeColorPicker(); });
  el('reset-all-colors-tokens')?.addEventListener('click', () => { resetCustomColors(); closeColorPicker(); });

  try {
    const presetGroup = el('heat-preset-group');
    if (presetGroup?.querySelectorAll) {
      for (const btn of presetGroup.querySelectorAll('[data-heat-preset]')) {
        btn.addEventListener('click', () => {
          const p = btn.getAttribute('data-heat-preset');
          if (p) setHeatPreset(p);
        });
      }
    }
  } catch {}

  // 颜色选取器内部控件绑定（SV 拖拽、Hue 拖拽、预设圆点、吸管、HEX/RGB/HSL 输入与复制）
  el('cp-close')?.addEventListener('click', () => closeColorPicker(false));
  el('cp-reset-slot')?.addEventListener('click', () => {
    if (activePickerSlot) {
      setCustomColor(activePickerSlot, '');
      const eff = getEffectiveSlotColor(activePickerSlot);
      const rgb = hexToRgb(eff) || { r: 101, g: 42, b: 183 };
      cpHsv = rgbToHsv(rgb.r, rgb.g, rgb.b);
      syncPickerUiFromHsv();
    }
  });

  try {
    const presetsWrap = el('cp-presets');
    if (presetsWrap?.querySelectorAll) {
      for (const dot of presetsWrap.querySelectorAll('[data-cp-hex]')) {
        dot.addEventListener('click', () => {
          const hex = dot.getAttribute('data-cp-hex');
          if (hex) applyPickerHex(hex);
        });
      }
    }
  } catch {}

  el('cp-eyedropper')?.addEventListener('click', async () => {
    const statusEl = el('cp-status-msg');
    try {
      if (typeof window !== 'undefined' && typeof window.EyeDropper === 'function') {
        const dropper = new window.EyeDropper();
        const res = await dropper.open();
        if (res?.sRGBHex) {
          applyPickerHex(res.sRGBHex);
          if (statusEl) statusEl.textContent = t('colors.eyedropperPicked', { hex: res.sRGBHex.toUpperCase() });
        }
      } else {
        el('cp-input-hex')?.focus?.();
        if (statusEl) statusEl.textContent = t('colors.eyedropperUnsupported');
      }
    } catch {}
  });

  el('cp-input-hex')?.addEventListener('input', e => {
    const raw = e.target?.value || '';
    const norm = normalizeHex(raw);
    if (norm) {
      applyPickerHex(norm, 'cp-input-hex');
      const statusEl = el('cp-status-msg');
      if (statusEl) statusEl.textContent = t('colors.appliedHex', { hex: norm.toUpperCase() });
    }
  });
  el('cp-input-hex')?.addEventListener('change', e => {
    const raw = e.target?.value || '';
    const norm = normalizeHex(raw);
    if (norm) applyPickerHex(norm);
  });

  el('cp-input-rgb')?.addEventListener('input', e => {
    const norm = normalizeHex(e.target?.value || '');
    if (norm) applyPickerHex(norm, 'cp-input-rgb');
  });
  el('cp-input-hsl')?.addEventListener('input', e => {
    const norm = normalizeHex(e.target?.value || '');
    if (norm) applyPickerHex(norm, 'cp-input-hsl');
  });

  function copyPickerText(inputId, label) {
    const input = el(inputId);
    const val = input?.value || '';
    if (!val) return;
    try {
      navigator?.clipboard?.writeText?.(val);
    } catch {}
    const statusEl = el('cp-status-msg');
    if (statusEl) statusEl.textContent = t('colors.copied', { label, val });
  }
  el('cp-copy-hex')?.addEventListener('click', () => copyPickerText('cp-input-hex', 'HEX'));
  el('cp-copy-rgb')?.addEventListener('click', () => copyPickerText('cp-input-rgb', 'RGB'));
  el('cp-copy-hsl')?.addEventListener('click', () => copyPickerText('cp-input-hsl', 'HSL'));

  const svAreaEl = el('cp-sv-area');
  const hueWrapEl = el('cp-hue-wrap');
  let draggingSv = false;
  let draggingHue = false;

  function updateSvFromPointer(e) {
    if (!svAreaEl?.getBoundingClientRect) return;
    const r = svAreaEl.getBoundingClientRect();
    if (!r.width || !r.height) return;
    const s = clampNum(((e.clientX - r.left) / r.width) * 100, 0, 100);
    const v = clampNum(100 - ((e.clientY - r.top) / r.height) * 100, 0, 100);
    cpHsv.s = Math.round(s);
    cpHsv.v = Math.round(v);
    const hex = syncPickerUiFromHsv();
    if (activePickerSlot) setCustomColor(activePickerSlot, hex);
  }

  function updateHueFromPointer(e) {
    if (!hueWrapEl?.getBoundingClientRect) return;
    const r = hueWrapEl.getBoundingClientRect();
    if (!r.width) return;
    const h = clampNum(((e.clientX - r.left) / r.width) * 360, 0, 360);
    cpHsv.h = Math.round(h);
    const hex = syncPickerUiFromHsv();
    if (activePickerSlot) setCustomColor(activePickerSlot, hex);
  }

  svAreaEl?.addEventListener('mousedown', e => {
    draggingSv = true;
    updateSvFromPointer(e);
  });
  hueWrapEl?.addEventListener('mousedown', e => {
    draggingHue = true;
    updateHueFromPointer(e);
  });
  const onPointerMove = e => {
    if (draggingSv) updateSvFromPointer(e);
    else if (draggingHue) updateHueFromPointer(e);
  };
  const onPointerUp = () => {
    draggingSv = false;
    draggingHue = false;
  };
  try {
    window.addEventListener?.('mousemove', onPointerMove);
    window.addEventListener?.('mouseup', onPointerUp);
  } catch {}
  // =========================================================================
  // 模块 2: 宿主布局挂载、右上角原生窗口控制区预留、渐进式宽度收缩与悬浮层定位
  // =========================================================================
  let resizeObserver = null;
  let hostDomObserver = null;
  let brandObserver = null;
  let observedTitlebar = null;
  let layoutRaf = 0;
  const earlyDisposeHooks = [];
  const disconnectBrandObserver = () => {
    try { brandObserver?.disconnect?.(); } catch { }
    if (brandObserver && globalThis.__AGContextMeterBrandObserver === brandObserver) {
      globalThis.__AGContextMeterBrandObserver = null;
    }
    brandObserver = null;
  };
  const earlyForceDispose = () => {
    state.disposed = true;
    radialDisposed = true;
    for (const controller of state.controllers) {
      try { controller.abort(); } catch { }
    }
    if (layoutRaf && typeof cancelAnimationFrame === 'function') {
      try { cancelAnimationFrame(layoutRaf); } catch { }
      layoutRaf = 0;
    }
    if (state.radialAlignTimer) {
      try { clearTimeout(state.radialAlignTimer); } catch { }
      state.radialAlignTimer = null;
    }
    while (earlyDisposeHooks.length) {
      const hook = earlyDisposeHooks.pop();
      try { hook(); } catch { }
    }
    try { resizeObserver?.disconnect?.(); } catch { }
    try { hostDomObserver?.disconnect?.(); } catch { }
    disconnectBrandObserver();
    if (globalThis.__AGContextMeterActiveHost === host) {
      globalThis.__AGContextMeterActiveHost = null;
    }
    activeDisposers.delete(earlyForceDispose);
    disposeRadialTopLayer();
    try { host.remove?.(); } catch { }
  };
  globalThis.__AGContextMeterActiveHost = host;
  host.__agForceDispose = earlyForceDispose;
  if (radialHost) radialHost.__agForceDispose = earlyForceDispose;
  activeDisposers.add(earlyForceDispose);

  function findHostTitlebar() {
    try {
      if (typeof document.querySelector !== 'function') return null;
      const candidates = typeof document.querySelectorAll === 'function'
        ? Array.from(document.querySelectorAll('[class*="@container/titlebar"]'))
        : [];
      if (candidates.length > 1) {
        // 多窗格下优先停靠最右上角窗格顶栏，避免被夹在分割线或下层窗格
        let best = null, bestTop = Infinity, bestRight = -Infinity;
        for (const node of candidates) {
          const rect = node?.getBoundingClientRect?.();
          if (!rect || (rect.width <= 0 && rect.height <= 0)) continue;
          const top = Number.isFinite(rect.top) ? rect.top : 0;
          const right = Number.isFinite(rect.right) ? rect.right : 0;
          if (!best || top < bestTop - 4 || (Math.abs(top - bestTop) <= 4 && right > bestRight)) {
            best = node; bestTop = top; bestRight = right;
          }
        }
        if (best) return best;
      }
      if (candidates.length === 1) return candidates[0];

      const byClass = document.querySelector('[class*="@container/titlebar"]');
      if (byClass) return byClass;

      // 回退方案：通过 "打开 IDE" / "Open IDE" 按钮反查其所属标题栏容器
      const allBtns = Array.from(document.querySelectorAll('button, a, [role="button"]') || []);
      const ideBtn = allBtns.find(b => {
        const text = (b?.textContent || '').trim();
        return text === 'Open IDE' || text === '打开 IDE' || text.includes('Open IDE') || text.includes('打开 IDE');
      });
      if (ideBtn) {
        const bar = ideBtn.closest('header, nav, [class*="titlebar"], [class*="toolbar"], div.flex.items-center');
        if (bar) return bar;
      }
      return null;
    } catch {
      return null;
    }
  }

  function isTopRightToolbarCluster(el) {
    if (!el || typeof el.getAttribute !== 'function') return false;
    const cls = el.className || '';
    if (typeof cls !== 'string') return false;
    const classList = typeof el.classList?.contains === 'function'
      ? el.classList
      : { contains: c => cls.split(/\s+/).includes(c) };
    if (!classList.contains('absolute') || !classList.contains('right-0')) return false;

    const styleTop = el.style?.top || el.getAttribute('style') || '';
    const hasTopClass = classList.contains('top-0');
    const hasTopStyle = /(?:^|;)\s*top:\s*0(?:px)?(?:\s*;|$)/i.test(styleTop);
    const rectTop = el.getBoundingClientRect ? el.getBoundingClientRect().top : 0;
    if (el.getBoundingClientRect && rectTop >= 20) return false;
    const isAtTop = hasTopClass || hasTopStyle || (rectTop <= 10 && rectTop >= 0);
    if (!isAtTop) return false;

    // 排除明显非顶栏容器（右侧全高抽屉、全屏浮层或带有明确非零高度下沉定位的浮层）
    if (classList.contains('bottom-0') || classList.contains('h-screen') || classList.contains('h-full')) {
      return false;
    }

    // 排除右侧滚动条滑槽（特征：包含 top-0.5 / bottom-0.5 / w-3 等滚动条特征）
    if (classList.contains('w-3') || classList.contains('right-0.5')) {
      return false;
    }

    // 必须符合顶栏控制按钮容器特征：
    // a) 包含右侧栏切换按钮
    // b) 或包含 z-50 并具有 flex / items-center 水平布局
    const hasAuxToggle = Boolean(el.querySelector && el.querySelector('[data-testid="toggle-aux-sidebar"]'));
    const hasToolbarLayout = classList.contains('z-50') && (classList.contains('items-center') || classList.contains('flex'));

    return hasAuxToggle || hasToolbarLayout;
  }

  function findTopRightCluster() {
    try {
      if (typeof document.querySelector !== 'function') return null;
      // 1. 优先从右侧栏切换按钮向上寻找最近的顶栏容器
      const auxToggle = document.querySelector('[data-testid="toggle-aux-sidebar"]');
      if (auxToggle?.closest) {
        // 先尝试带 top-0 的经典结构（Antigravity 1.x）
        let cluster = auxToggle.closest('div.absolute.right-0.top-0');
        if (cluster && isTopRightToolbarCluster(cluster)) return cluster;
        // 兼容 Antigravity 2.x（top: 0px 写在内联 style，class 无 top-0）
        cluster = auxToggle.closest('div.absolute.right-0');
        if (cluster && isTopRightToolbarCluster(cluster)) return cluster;
      }

      // 2. 备用安全探测：当 auxToggle 尚未挂载或被动态卸载时，精确匹配顶栏容器
      // 严格检查顶部坐标与容器特征，绝不误伤滚动条、侧栏抽屉或模态弹窗
      const selectors = [
        'div.h-screen.w-screen > div.flex-1 > div.absolute.right-0.top-0.z-50',
        'div.h-screen.w-screen > div.flex-1 > div.absolute.right-0.z-50',
        'div.absolute.right-0.z-50'
      ];
      for (const sel of selectors) {
        const el = document.querySelector(sel);
        if (el && isTopRightToolbarCluster(el)) return el;
      }
      return null;
    } catch {
      return null;
    }
  }

  // 动态计算右上角原生窗口控制区（Minimize / Maximize / Close）独占宽度（CSS px）
  function computeWindowControlsWidth(topRight) {
    if (!topRight) return 0;
    try {
      const plat = (typeof navigator !== 'undefined' && navigator.platform) || '';
      if (/^Mac|iPhone|iPad/i.test(plat)) return 0;
      if (topRight?.getBoundingClientRect) {
        const tr = topRight.getBoundingClientRect();
        // 若顶部已单独渲染菜单栏（top >= 20），则 40px 工具栏不在窗口顶边，无需重复留白
        if (tr.height > 0 && tr.top >= 20) return 0;
      }
      const vw = (typeof window !== 'undefined' && window.innerWidth) || 0;
      // 优先 1: 标准 WCO 接口 navigator.windowControlsOverlay
      const wco = typeof navigator !== 'undefined' ? navigator.windowControlsOverlay : null;
      if (wco?.visible && typeof wco.getTitlebarAreaRect === 'function') {
        const rect = wco.getTitlebarAreaRect();
        if (rect && rect.width > 0 && vw > 0 && rect.width < vw) {
          return Math.max(0, Math.ceil(vw - rect.right));
        }
      }
      // 优先 2: 根据 Electron titleBarOverlay 几何规格（Windows 3 颗原生控制按钮共 138 OS DIP）与实时缩放比动态换算
      let zoomFactor = 1;
      if (typeof window !== 'undefined') {
        const nativeZoom = window.electronNative?.getZoomLevel?.();
        if (typeof nativeZoom === 'number' && nativeZoom >= 0.25 && nativeZoom <= 5) {
          zoomFactor = nativeZoom;
        } else if (window.outerWidth > 0 && window.innerWidth > 0) {
          const ratio = window.outerWidth / window.innerWidth;
          if (ratio >= 0.25 && ratio <= 5) zoomFactor = ratio;
        }
      }
      const rawCssWidth = Math.ceil(138 / zoomFactor);
      let existingSpacerWidth = 0;
      if (topRight?.querySelectorAll) {
        const spacers = topRight.querySelectorAll('div[aria-hidden="true"]');
        for (const sp of spacers) {
          if (sp.id !== 'ag-wco-spacer' && sp.getBoundingClientRect) {
            existingSpacerWidth += Math.round(sp.getBoundingClientRect().width || parseFloat(sp.style?.width) || 0);
          }
        }
      }
      return Math.max(0, rawCssWidth - existingSpacerWidth);
    } catch {
      return 98;
    }
  }

  function syncWindowControlsOverlay() {
    if (state.disposed) return;
    try {
      const topRight = findTopRightCluster();
      const wcoWidth = computeWindowControlsWidth(topRight);
      const spacer = typeof document.getElementById === 'function' ? document.getElementById('ag-wco-spacer') : null;
      if (topRight && typeof document.createElement === 'function' && wcoWidth > 0) {
        let activeSpacer = spacer;
        if (!activeSpacer || activeSpacer.parentElement !== topRight) {
          activeSpacer?.remove?.();
          activeSpacer = document.createElement('div');
          activeSpacer.id = 'ag-wco-spacer';
          activeSpacer.setAttribute('aria-hidden', 'true');
          topRight.appendChild(activeSpacer);
        }
        const targetCss = `width:${wcoWidth}px;height:100%;flex-shrink:0;pointer-events:none;`;
        if (activeSpacer.style.cssText !== targetCss) {
          activeSpacer.style.cssText = targetCss;
        }
      } else {
        if (spacer) {
          spacer.remove();
        }
        if (topRight?.querySelectorAll) {
          const oldSpacers = topRight.querySelectorAll('#ag-wco-spacer');
          for (const s of oldSpacers) {
            s.remove?.();
          }
        }
      }

      // 主对话区顶栏若处于窗口最顶行（无独立菜单栏，top < 20）且靠最右边，需同步避让系统控制按钮及右侧独立浮动簇
      let titlebarWcoPad = 0;
      const titlebar = findHostTitlebar();
      if (titlebar?.getBoundingClientRect) {
        const tbRect = titlebar.getBoundingClientRect();
        const vw = (typeof window !== 'undefined' && window.innerWidth) || 0;
        if (tbRect.height > 0 && tbRect.top < 20 && (vw <= 0 || tbRect.right >= vw - 16)) {
          const baseWco = computeWindowControlsWidth(titlebar);
          if (baseWco > 0) {
            titlebarWcoPad = baseWco;
            if (topRight && topRight !== titlebar && !titlebar.contains?.(topRight) && topRight.getBoundingClientRect) {
              const trRect = topRight.getBoundingClientRect();
              if (trRect.width > 0 && trRect.top < 20 && vw > 0 && trRect.left < vw) {
                titlebarWcoPad = Math.max(titlebarWcoPad, Math.ceil(vw - trRect.left) + 6);
              }
            }
          }
        }
      }

      if (typeof document.head !== 'undefined' && document.head && typeof document.createElement === 'function') {
        let styleEl = typeof document.getElementById === 'function' ? document.getElementById('ag-topbar-host-fix') : null;
        if (!styleEl) {
          styleEl = document.createElement('style');
          styleEl.id = 'ag-topbar-host-fix';
          document.head.appendChild(styleEl);
        }
        const activeWco = wcoWidth > 0 || titlebarWcoPad > 0;
        const cssText = [
          '[data-aux-pane-focus-scope="true"] > div[data-active-tab-id] {',
          '  padding-right: calc(var(--right-cluster-width, 140px) - 4px) !important;',
          '}',
          titlebarWcoPad > 0 ? [
            '[class*="@container/titlebar"] {',
            `  padding-right: ${titlebarWcoPad}px !important;`,
            '}'
          ].join('\n') : '',
          activeWco ? [
            '[class*="@container/titlebar"],',
            '[data-aux-pane-focus-scope="true"] > div[data-active-tab-id],',
            'div[role="navigation"][aria-label] > div.shrink-0:first-child {',
            '  /* Native titlebar owns draggable regions. */',
            '}',
            '[class*="@container/titlebar"] button,',
            '[class*="@container/titlebar"] a,',
            '[class*="@container/titlebar"] input,',
            '[class*="@container/titlebar"] [role="button"],',
            '[data-testid="pane-titlebar-toolbar"] > *,',
            '[data-aux-pane-focus-scope="true"] > div[data-active-tab-id] button,',
            '[data-aux-pane-focus-scope="true"] > div[data-active-tab-id] [data-tab-id],',
            'div[role="navigation"][aria-label] > div.shrink-0:first-child button,',
            'div[role="navigation"][aria-label] > div.shrink-0:first-child a,',
            '#ag-context-meter {',
            '  -webkit-app-region: no-drag;',
            '}'
          ].join('\n') : '',
          // 无论是否存在 WCO 宽度，始终强制顶栏容器与内部控件可点击且不触发窗口拖动
          '#ag-context-meter, #ag-context-meter * { -webkit-app-region: no-drag !important; pointer-events: auto; }'
        ].join('\n');
        if (styleEl.textContent !== cssText) {
          styleEl.textContent = cssText;
        }
      }
      syncNativeOverlayTheme();
    } catch { }
  }

  let layoutMeasurementDirty = true;
  let cachedMeasuredAvailWidth = null;
  let cachedMeasuredAvailAt = 0;
  let cachedMeasuredWinWidth = 0;

  function isSearchOrFilterTextbox(node) {
    if (!node) return false;
    try {
      const type = String(node.type || node.getAttribute?.('type') || '').toLowerCase();
      if (type === 'search') return true;
      const meta = [
        node.getAttribute?.('placeholder'),
        node.getAttribute?.('aria-label'),
        node.getAttribute?.('name'),
        node.getAttribute?.('data-testid')
      ].filter(Boolean).join(' ').toLowerCase();
      if (/\b(search|filter|find|extension|plugin|marketplace)\b|搜索|过滤|筛选|扩展|插件/.test(meta)) return true;
      if (node.closest?.('[data-testid*="customization"], [data-testid*="marketplace"], [class*="customization"], [class*="marketplace"]')) {
        return true;
      }
    } catch { }
    return false;
  }

  function hasRealChatComposer() {
    try {
      const selectors = '[data-testid="composer"], [data-testid="chat-input"], [data-testid="prompt-input"], textarea, [contenteditable="true"], [role="textbox"]';
      let candidates = [];
      if (typeof document?.querySelectorAll === 'function') {
        candidates = Array.from(document.querySelectorAll(selectors) || []);
      }
      if (!candidates.length && typeof document?.querySelector === 'function') {
        for (const singleSel of selectors.split(',')) {
          const hit = document.querySelector(singleSel.trim());
          if (hit) candidates.push(hit);
        }
      }
      for (const node of candidates) {
        if (!node) continue;
        if (typeof host?.contains === 'function' && host.contains(node)) continue;
        if (node.closest?.('#ag-context-meter')) continue;
        if (isSearchOrFilterTextbox(node)) continue;
        if (typeof node.getBoundingClientRect === 'function') {
          const rect = node.getBoundingClientRect();
          if (rect && Number(rect.width) === 0 && Number(rect.height) === 0) continue;
        }
        return true;
      }
    } catch { }
    return false;
  }

  function isHostNavOrSideUtilityNode(node) {
    if (!node) return false;
    try {
      if (typeof host?.contains === 'function' && host.contains(node)) return true;
      if (node.closest?.('#ag-context-meter')) return true;
      if (node.closest?.('nav, aside, [data-side-panel-open], [data-side-panel-focus-scope]')) return true;
      if (node.tagName === 'A' && node.getAttribute?.('href')) return true;
    } catch { }
    return false;
  }

  function hasActiveConversationContentInDom() {
    try {
      if (typeof document?.querySelector !== 'function') return false;
      return Boolean(
        document.querySelector('[data-testid="conversation-view"], [data-testid="cascade-system-message-toolbar"], .ag-cm-turn-footer')
      );
    } catch { return false; }
  }

  function isNonConversationSubview() {
    return isHostMarketplaceActive();
  }

  function isHostMarketplaceActive() {
    try {
      const locPath = String(typeof location !== 'undefined' ? (location.pathname || '') : '');
      const locHash = String(typeof location !== 'undefined' ? (location.hash || '') : '');
      const locCombined = `${locPath} ${locHash}`.toLowerCase();
      if (/(?:^|\/|#)(?:extensions|marketplace|customizations|installed|plugin|plugins)(?:\/|$|\?|#)/i.test(locCombined)) {
        return true;
      }
      if (typeof document?.querySelector !== 'function') return false;
      const customNav = document.querySelector(
        '[data-testid*="customization"].active, [data-testid*="marketplace"].active, [data-testid*="installed"].active, '
        + '[aria-label*="自定义"].active, [aria-label*="Customization"].active, '
        + 'button[aria-selected="true"][data-testid*="customization"], button[aria-selected="true"][data-testid*="marketplace"], '
        + '[role="tab"][aria-selected="true"][data-testid*="customization"], [role="tab"][aria-selected="true"][data-testid*="marketplace"], '
        + '[aria-current="page"][data-testid*="customization"], [aria-current="page"][data-testid*="marketplace"]'
      );
      if (customNav && !host?.contains?.(customNav) && !customNav.closest?.('#ag-context-meter')) return true;

      // 仅把真正的对话输入框视为聊天视图，自定义扩展/插件市场中的搜索框不得触发误放行
      const hasComposer = hasRealChatComposer();
      if (hasComposer) return false;

      // 排除左侧常驻导航/右侧工具栏；移除单字泛词防止命中无关菜单标签
      const headings = typeof document?.querySelectorAll === 'function'
        ? Array.from(document.querySelectorAll('h1, h2, h3, [role="heading"], [role="tab"][aria-selected="true"], button[aria-selected="true"]'))
        : [];
      const CUSTOMIZATION_TITLES = new Set([
        '自定义扩展', '插件市场', '已安装', '自定义扩展与技能',
        'Marketplace', 'Customizations', 'Customizations & Skills', 'Installed', 'Plugins', 'Extensions',
        'Browse the Marketplace'
      ]);
      const hasHeading = headings.some(node => {
        if (!node || isHostNavOrSideUtilityNode(node)) return false;
        const txt = String(node.textContent || '').trim();
        return CUSTOMIZATION_TITLES.has(txt);
      });
      if (hasHeading) return true;

      // 若页面明确处于带消息记录的会话视图（含无输入框的已归档历史会话 /c/...），不再走宽松的全局 Back 猜测
      if (hasActiveConversationContentInDom()) return false;

      // 兼容插件详情子页：顶部标题切换为具体插件名，出现 Back 返回按钮且存在扩展容器或安装/启用操作
      const backBtn = document.querySelector('button[aria-label*="Back"], button[aria-label*="返回"], [data-testid*="back"]');
      const hasHostBack = Boolean(backBtn && !isHostNavOrSideUtilityNode(backBtn));
      if (hasHostBack) {
        const customContainerNodes = typeof document?.querySelectorAll === 'function'
          ? Array.from(document.querySelectorAll('[data-testid*="customization"], [class*="customization"], [data-testid*="marketplace"], [class*="marketplace"]'))
          : [];
        const hasMainCustomContainer = customContainerNodes.some(node => node && !isHostNavOrSideUtilityNode(node));
        if (hasMainCustomContainer) {
          return true;
        }
        const actionNodes = typeof document?.querySelectorAll === 'function'
          ? Array.from(document.querySelectorAll('button, [role="button"]'))
          : [];
        const hasPluginDetailAction = actionNodes.some(btn => {
          if (!btn || isHostNavOrSideUtilityNode(btn)) return false;
          const label = String(btn.textContent || '').trim();
          return /^(Install|Uninstall|Enable|Disable|Configure|Connect|\+\s*Add|Details|安装|卸载|启用|禁用|移除|配置|详情)$/i.test(label);
        });
        if (hasPluginDetailAction && !document.querySelector('[data-testid="conversation-view"]')) {
          return true;
        }
      }
      return false;
    } catch { return false; }
  }

  function enforceMarketplaceAvoidance(forceActive) {
    const active = typeof forceActive === 'boolean' ? forceActive : isHostMarketplaceActive();
    try {
      if (active) {
        host.setAttribute('data-marketplace-active', 'true');
        if (typeof clearBadgeLongPress === 'function') clearBadgeLongPress();
        if (typeof cancelClosePanelPicker === 'function') cancelClosePanelPicker();
        if (typeof closeRadialMenu === 'function') closeRadialMenu(true);
        state.tooltipOpen = false;
        for (const id of ['panel', 'panel-tokens', 'panel-quota', 'overflow-menu', 'ctx-radial-orb', 'ctx-radial-layer', 'token-five-line-card', 'dock-aux-context-bar', 'composer-status-bar']) {
          const node = el(id);
          if (node) {
            node.hidden = true;
            if (node.style && (id === 'token-five-line-card' || id === 'overflow-menu' || id === 'ctx-radial-orb' || id === 'ctx-radial-layer')) {
              node.style.display = 'none';
              node.style.pointerEvents = 'none';
            }
          }
        }
        const tip = el('context-tooltip');
        if (tip) tip.setAttribute('data-visible', 'false');
        const upPop = el('update-popover');
        if (upPop && upPop.style) upPop.style.display = 'none';
        if (typeof hidePopover === 'function') hidePopover();
        for (const bid of ['badge', 'badge-speed', 'badge-tokens', 'badge-quota', 'badge-overflow', 'badge-dock-wake']) {
          const btn = el(bid);
          btn?.setAttribute?.('aria-expanded', 'false');
          btn?.removeAttribute?.('data-picker-open');
        }
        if (typeof syncHostStackingElevation === 'function') syncHostStackingElevation(false);
        if (typeof syncDockedPanelsAttribute === 'function') syncDockedPanelsAttribute();
        if (typeof syncPanelPickerActiveState === 'function') syncPanelPickerActiveState();
      } else {
        const hadAttr = host.getAttribute?.('data-marketplace-active') === 'true';
        if (hadAttr) {
          host.removeAttribute('data-marketplace-active');
          const tflCard = el('token-five-line-card');
          if (tflCard && tflCard.hidden && tflCard.style) tflCard.style.display = 'none';
          const ovMenu = el('overflow-menu');
          if (ovMenu && ovMenu.style) {
            ovMenu.style.display = '';
            ovMenu.style.pointerEvents = '';
          }
          const csbBar = el('composer-status-bar');
          if (csbBar) csbBar.hidden = false;
          const orbEl = el('ctx-radial-orb');
          if (orbEl && orbEl.style) {
            orbEl.style.display = '';
            orbEl.style.pointerEvents = '';
          }
          const radialEl = el('ctx-radial-layer');
          if (radialEl && radialEl.style) {
            radialEl.style.display = '';
            radialEl.style.pointerEvents = '';
          }
          if (typeof syncRadialOrbVisibility === 'function') syncRadialOrbVisibility();
          if (typeof syncAuxContextBar === 'function') syncAuxContextBar();
        }
      }
    } catch { }
    return active;
  }

  function findAuxSidebarContainer() {
    try {
      // 1. 优先识别 Antigravity 2.34.0 展开态右侧辅助栏 ([data-side-panel-open="true"] / [data-aux-pane-open="true"])
      if (typeof document?.querySelectorAll === 'function') {
        const modernCandidates = Array.from(document.querySelectorAll(
          '[data-side-panel-open="true"] [data-side-panel-focus-scope="true"], [data-aux-pane-open="true"] [data-side-panel-focus-scope="true"]'
        ) || []);
        const visibleModern = modernCandidates.filter(node => {
          if (!node) return false;
          if (typeof node.getBoundingClientRect === 'function') {
            const rect = node.getBoundingClientRect();
            const hasBox = rect && (Number(rect.height) > 0 || Number(rect.top) > 0 || Number(rect.left) > 0);
            if (hasBox && Number(rect.width) <= 120) return false;
          }
          return true;
        });
        if (visibleModern.length > 0) {
          const outerStripHost = visibleModern.find(n => {
            try { return Boolean(n.querySelector?.('[data-side-panel-strip="true"], [data-side-panel-strip]')); } catch { return false; }
          });
          return outerStripHost || visibleModern[0];
        }
      }
      if (typeof document?.querySelector !== 'function') return null;
      // 2. 兼容旧版宿主与单元测 DOM ([data-aux-pane-focus-scope="true"])
      const auxScope = document.querySelector('[data-aux-pane-focus-scope="true"]');
      if (auxScope) {
        if (typeof auxScope.getBoundingClientRect === 'function') {
          const rect = auxScope.getBoundingClientRect();
          const hasBox = rect && (Number(rect.height) > 0 || Number(rect.top) > 0 || Number(rect.left) > 0);
          if (hasBox && Number(rect.width) <= 120 && !auxScope.querySelector?.('div[data-active-tab-id]')) {
            return null;
          }
        }
        const tabContent = auxScope.querySelector?.('div[data-active-tab-id]') || auxScope;
        return tabContent;
      }
      // 3. 回退常见 VS Code / Electron 右侧栏容器
      const legacy = document.querySelector(
        '[data-testid="aux-sidebar"], [data-testid="right-sidebar"], [id="workbench.parts.auxiliarybar"], .auxiliary-bar, .part.auxiliarybar'
      );
      if (legacy && typeof legacy.getBoundingClientRect === 'function') {
        const lr = legacy.getBoundingClientRect();
        const hasBox = lr && (Number(lr.height) > 0 || Number(lr.top) > 0 || Number(lr.left) > 0);
        if (hasBox && Number(lr.width) <= 120) return null;
      }
      return legacy;
    } catch { return null; }
  }

  function isAuxSidebarExpanded() {
    try {
      const auxToggle = document?.querySelector?.('[data-testid="toggle-aux-sidebar"]');
      if (auxToggle?.getAttribute?.('aria-expanded') === 'true') return true;
      if (document?.querySelector?.('[data-side-panel-open="true"], [data-aux-pane-open="true"]')) return true;
      return Boolean(findAuxSidebarContainer());
    } catch { return false; }
  }

  async function ensureAuxSidebarExpanded({ timeoutMs = 1000 } = {}) {
    const existing = findAuxSidebarContainer();
    if (existing) return existing;
    const auxToggle = document?.querySelector?.('[data-testid="toggle-aux-sidebar"]');
    if (auxToggle && !isAuxSidebarExpanded()) {
      try { auxToggle.click(); } catch { }
    }
    const immediate = findAuxSidebarContainer();
    if (immediate) return immediate;
    const deadline = Date.now() + Math.max(0, Number(timeoutMs) || 0);
    while (Date.now() < deadline && !state.disposed) {
      await new Promise(resolve => setTimeout(resolve, 50));
      const found = findAuxSidebarContainer();
      if (found) return found;
    }
    return findAuxSidebarContainer();
  }

  async function copyTextToClipboardSafe(text) {
    if (!text) return false;
    if (typeof navigator !== 'undefined' && typeof navigator?.clipboard?.writeText === 'function') {
      try {
        await navigator.clipboard.writeText(String(text));
        return true;
      } catch { }
    }
    return false;
  }

  function formatAuxRoleText(focusTarget) {
    if (focusTarget?.isSideChat) return t('settings.dock.auxRoleSideChat');
    if (focusTarget?.kind === 'split' || (state.layout?.panes?.length || 0) > 1) return t('settings.dock.auxRoleSplit');
    return t('settings.dock.auxRoleMain');
  }

  function syncAuxContextBar() {
    const bar = el('dock-aux-context-bar');
    const lbl = el('dock-aux-session-label');
    const marketplaceBlocked = isHostMarketplaceActive();
    const activeAux = !marketplaceBlocked && dockPosition === 'aux' && !dockFallbackReason;
    if (bar) bar.hidden = !activeAux;
    if (lbl) {
      const ft = resolveFocusedSessionTarget();
      if (ft?.sessionId) {
        lbl.textContent = t('settings.dock.auxFollowing', {
          role: formatAuxRoleText(ft),
          id: ft.sessionId.slice(0, 8)
        });
        lbl.title = ft.sessionId;
      } else {
        lbl.textContent = t('settings.dock.auxUnresolved');
        lbl.title = '';
      }
    }
  }

  function findEditorPageContainer() {
    try {
      if (typeof document?.querySelector !== 'function') return null;
      const standard = document.querySelector('[id="workbench.parts.editor"], .editor-group-container, main[role="main"], .monaco-workbench .part.editor');
      if (standard) return standard;
      const convView = document.querySelector('[data-testid="conversation-view"]');
      if (convView && (!host || !host.contains?.(convView))) {
        return convView.parentElement || convView;
      }
      const hubMain = document.querySelector('[data-main-pane], [data-testid="chat-pane"], main');
      if (hubMain && (!host || !host.contains?.(hubMain))) return hubMain;
      return null;
    } catch { return null; }
  }

  function syncDockCollapsedTopbar() {
    const isDockedActive = (panelDockMode === 'aux' || panelDockMode === 'page' || dockPosition === 'aux' || dockPosition === 'page') && !dockFallbackReason;
    const isPanelOpen = ['panel', 'panel-tokens', 'panel-quota'].some(id => {
      const p = el(id);
      return p && !p.hidden && p.style.display !== 'none';
    });
    if (isDockedActive && isPanelOpen && autoHideTopbarOnDockedPanel) {
      host.setAttribute('data-dock-collapsed-topbar', 'true');
    } else {
      host.removeAttribute('data-dock-collapsed-topbar');
    }
  }

  function syncDockPositionUi() {
    // 1. 顶栏入口形态分段器
    const topbarSeg = el('topbar-mode-segmented');
    if (topbarSeg) {
      for (const btn of Array.from(topbarSeg.children || [])) {
        const mode = btn.getAttribute?.('data-topbar-mode');
        const active = mode === topbarMode;
        btn.classList?.toggle?.('active', active);
        btn.setAttribute?.('aria-pressed', active ? 'true' : 'false');
      }
    }
    const topbarDescEl = el('topbar-mode-desc');
    if (topbarDescEl) {
      topbarDescEl.textContent = t(`settings.topbarMode.${topbarMode}Desc`) || '';
    }

    // 2. 面板显示位置分段器
    const panelSeg = el('panel-dock-mode-segmented');
    if (panelSeg) {
      for (const btn of Array.from(panelSeg.children || [])) {
        const mode = btn.getAttribute?.('data-panel-dock-mode');
        const active = mode === panelDockMode;
        btn.classList?.toggle?.('active', active);
        btn.setAttribute?.('aria-pressed', active ? 'true' : 'false');
      }
    }
    const panelDescEl = el('panel-dock-mode-desc');
    if (panelDescEl) {
      panelDescEl.textContent = t(`settings.panelDockMode.${panelDockMode}Desc`) || '';
    }

    // 3. 联动与兼容复选框
    const chkAutoCol = el('chk-autohide-topbar-docked');
    if (chkAutoCol) {
      chkAutoCol.checked = Boolean(autoHideTopbarOnDockedPanel);
    }
    const chkHide = el('chk-hide-topbar');
    if (chkHide) {
      chkHide.checked = Boolean(isTopbarHidden || topbarMode === 'hidden');
    }

    // 4. 兼容旧分段器与说明
    const seg = el('dock-pos-segmented');
    if (seg) {
      for (const btn of Array.from(seg.children || [])) {
        const mode = btn.getAttribute?.('data-dock-mode');
        const active = mode === dockPosition;
        btn.classList?.toggle?.('active', active);
        btn.setAttribute?.('aria-pressed', active ? 'true' : 'false');
      }
    }
    const descEl = el('dock-mode-desc');
    if (descEl) {
      const descKey = `settings.dock.${dockPosition}Desc`;
      descEl.textContent = t(descKey) || '';
    }

    const noteEl = el('dock-fallback-note');
    if (noteEl) {
      let fbRaw = '';
      if (dockFallbackReason === 'aux') {
        fbRaw = t('settings.dock.fallbackAux');
      } else if (dockFallbackReason === 'page') {
        fbRaw = t('settings.dock.fallbackPage');
      }
      const fbTxt = String(fbRaw || '').trim();
      if (fbTxt) {
        noteEl.hidden = false;
        noteEl.textContent = fbTxt;
      } else {
        noteEl.hidden = true;
        noteEl.textContent = '';
      }
    }
    const pageActions = el('dock-page-actions');
    if (pageActions) {
      pageActions.style.display = (panelDockMode === 'page' || dockPosition === 'page') ? 'block' : 'none';
    }
    // “返回聊天”按钮仅在独立页面模式且未回退时显示
    const pageBackBtn = el('btn-dock-page-back');
    if (pageBackBtn) {
      pageBackBtn.hidden = !((panelDockMode === 'page' || dockPosition === 'page') && !dockFallbackReason);
    }
    const wakeBtn = el('badge-dock-wake');
    if (wakeBtn) {
      wakeBtn.hidden = !(isTopbarHidden || topbarMode === 'hidden');
    }
    syncQuickMenuStyleUi();
    syncAuxContextBar();
    syncDockCollapsedTopbar();
    const fbActions = el('dock-fallback-actions');
    const fbEl = el('dock-open-feedback');
    if (fbEl && !String(fbEl.textContent || '').trim()) {
      fbEl.hidden = true;
      fbEl.textContent = '';
    }
    if (fbActions) {
      fbActions.hidden = !((fbEl && !fbEl.hidden) || dockFallbackReason === 'aux' || dockFallbackReason === 'page');
    }
  }

  function syncDockedPanelsAttribute() {
    const docked = (panelDockMode === 'aux' || panelDockMode === 'page' || dockPosition === 'aux' || dockPosition === 'page') && !dockFallbackReason;
    for (const id of ['panel', 'panel-tokens', 'panel-quota']) {
      const p = el(id);
      if (!p) continue;
      if (docked) {
        p.setAttribute?.('data-panel-docked', 'true');
      } else {
        const wasDocked = p.getAttribute?.('data-panel-docked') === 'true' || p.style?.position === 'static';
        p.removeAttribute?.('data-panel-docked');
        if (p.style && p.style.position === 'static') p.style.position = '';
        if (wasDocked) p._lastPlacedGeomKey = null;
      }
    }
  }

  function setTopbarMode(mode, opts = {}) {
    let next = mode;
    if (!VALID_TOPBAR_MODES.includes(mode)) next = 'full';
    topbarMode = next;
    isTopbarHidden = next === 'hidden';
    // 兼容维护旧 dockPosition，且 page 模式不得覆盖持久化为 page
    if (panelDockMode === 'aux') {
      dockPosition = 'aux';
    } else if (panelDockMode === 'page') {
      dockPosition = 'page';
    } else {
      dockPosition = topbarMode === 'compact' ? 'compact' : 'flow';
    }
    const persistDock = dockPosition === 'page' ? 'flow' : dockPosition;
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('ag_topbar_mode', topbarMode);
        localStorage.setItem('ag_hide_topbar', isTopbarHidden ? 'true' : 'false');
        localStorage.setItem('ag_dock_position', persistDock);
      }
    } catch { }
    host.setAttribute('data-topbar-mode', topbarMode);
    if (isTopbarHidden) {
      host.setAttribute('data-topbar-hidden', 'true');
    } else {
      host.removeAttribute('data-topbar-hidden');
    }
    host.setAttribute('data-dock', dockPosition);
    layoutMeasurementDirty = true;
    ensureHostDocked();
    syncDockPositionUi();
    if (opts.persist !== false && (typeof window?.contextMeterAPI?.saveSettings === 'function' || hasLiveHttpBridge())) {
      void saveSettingsPayloadBridge({
        topbarMode,
        hideTopbar: isTopbarHidden,
        dockPosition: persistDock
      });
    }
    return topbarMode;
  }

  function setPanelDockMode(mode, opts = {}) {
    let next = mode;
    if (!VALID_PANEL_DOCK_MODES.includes(mode)) next = 'popover';
    panelDockMode = next;
    // 严格保持用户当前 topbarMode，绝不强行将顶栏恢复为 full
    if (panelDockMode === 'aux') {
      dockPosition = 'aux';
    } else if (panelDockMode === 'page') {
      dockPosition = 'page';
    } else {
      dockPosition = topbarMode === 'compact' ? 'compact' : 'flow';
    }
    const persistDock = dockPosition === 'page' ? 'flow' : dockPosition;
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('ag_panel_dock_mode', panelDockMode);
        localStorage.setItem('ag_dock_position', persistDock);
      }
    } catch { }
    host.setAttribute('data-panel-dock-mode', panelDockMode);
    host.setAttribute('data-dock', dockPosition);
    layoutMeasurementDirty = true;
    ensureHostDocked();
    syncDockPositionUi();
    syncDockedPanelsAttribute();
    if (opts.persist !== false && (typeof window?.contextMeterAPI?.saveSettings === 'function' || hasLiveHttpBridge())) {
      void saveSettingsPayloadBridge({
        panelDockMode,
        dockPosition: persistDock
      });
    }
    return panelDockMode;
  }

  function setAutoHideTopbarOnDockedPanel(enable, opts = {}) {
    autoHideTopbarOnDockedPanel = Boolean(enable);
    try {
      if (typeof localStorage !== 'undefined') localStorage.setItem('ag_autohide_topbar_docked', autoHideTopbarOnDockedPanel ? 'true' : 'false');
    } catch { }
    syncDockCollapsedTopbar();
    syncDockPositionUi();
    if (opts.persist !== false && (typeof window?.contextMeterAPI?.saveSettings === 'function' || hasLiveHttpBridge())) {
      void saveSettingsPayloadBridge({
        autoHideTopbarOnDockedPanel
      });
    }
    return autoHideTopbarOnDockedPanel;
  }

  function setDockPosition(mode, opts = {}) {
    let next = mode;
    if (mode === 'hide') {
      setTopbarMode('hidden', opts);
      return 'hide';
    }
    if (mode === 'compact' || mode === 'fixed') {
      setTopbarMode('compact', opts);
      setPanelDockMode('popover', opts);
      return 'compact';
    }
    if (mode === 'aux') {
      setPanelDockMode('aux', opts);
      return 'aux';
    }
    if (mode === 'page') {
      setPanelDockMode('page', opts);
      return 'page';
    }
    setTopbarMode('full', opts);
    setPanelDockMode('popover', opts);
    return 'flow';
  }

  function setHideTopbar(hidden, opts = {}) {
    const isHide = Boolean(hidden);
    setTopbarMode(isHide ? 'hidden' : 'full', opts);
  }

  function resolveFocusedSessionTarget() {
    try {
      const layout = typeof parseConversationLayout === 'function' ? parseConversationLayout() : null;
      const resolved = layout ? resolveEffectiveRoute(layout, false) : null;
      const targetId = resolved || state.route || null;
      const targetMeta = (layout?.targets || []).find(item => sameRouteId(item.id, targetId)) || null;
      return {
        sessionId: targetId,
        source: 'desktop',
        role: targetMeta?.role || 'pane',
        kind: targetMeta?.kind || 'pane',
        isSideChat: targetMeta?.role === 'sidechat'
      };
    } catch {
      return { sessionId: state.route || null, source: 'desktop', role: 'pane', kind: 'pane', isSideChat: false };
    }
  }

  function setDockOpenFeedback(msg, isWarn = false, { showActions = true } = {}) {
    const fb = el('dock-open-feedback');
    const fbActions = el('dock-fallback-actions');
    const cleanMsg = String(msg || '').trim();
    if (fb) {
      if (!cleanMsg) {
        fb.hidden = true;
        fb.textContent = '';
        if (fbActions && !dockFallbackReason) fbActions.hidden = true;
      } else {
        fb.hidden = false;
        fb.textContent = cleanMsg;
        fb.style.color = isWarn ? 'var(--ag-ring-warn, #f59e0b)' : 'var(--ag-text-secondary)';
        if (fbActions) fbActions.hidden = !showActions;
      }
    }
    const toast = el('cli-launch-toast');
    if (toast && cleanMsg) {
      toast.textContent = cleanMsg;
      toast.hidden = false;
      toast.setAttribute('data-tone', isWarn ? 'warn' : 'info');
      clearTimeout(toast.__hideTimer);
      toast.__hideTimer = setTimeout(() => { toast.hidden = true; }, 4500);
    }
  }

  async function resolvePreciseDashboardUrl({ openExternal = false } = {}) {
    const focusTarget = resolveFocusedSessionTarget();
    const payload = {
      sessionId: focusTarget.sessionId || null,
      source: focusTarget.source || 'desktop',
      openExternal: Boolean(openExternal)
    };
    if (typeof window?.contextMeterAPI?.openDashboardBrowser === 'function') {
      try {
        const res = await window.contextMeterAPI.openDashboardBrowser(payload);
        if (res && res.ok && res.url) {
          return { ...res, focusTarget };
        }
      } catch { }
    }
    if (typeof callBackendWithPriority === 'function') {
      try {
        const out = await callBackendWithPriority({
          liveRoute: '/open-dashboard-browser',
          liveBody: payload
        });
        const res = out?.result || out;
        if (res && res.ok && res.url) {
          return { ...res, focusTarget };
        }
      } catch { }
    }
    return { ok: false, focusTarget, error: '独立看板服务未就绪' };
  }

  async function openDashboardInRightPanel() {
    if (enforceMarketplaceAvoidance()) {
      return { ok: false, blocked: 'marketplace', mode: 'blocked' };
    }
    const focusTarget = resolveFocusedSessionTarget();
    // 1. 仅在辅助栏未展开时触发 toggle，并异步等待 2.34.0 右侧容器动画/挂载就绪后再执行停靠
    try {
      await ensureAuxSidebarExpanded({ timeoutMs: 1000 });
      setDockPosition('aux', { persist: true });
      if (typeof switchContextTab === 'function') switchContextTab('session');
      showPanel('context');
    } catch { }

    // 2. 生成当前聚焦会话的精确看板 URL 并尝试复制到剪贴板，明确告知宿主 built-in browser 接口限制与可用动作
    const srvRes = await resolvePreciseDashboardUrl({ openExternal: false });
    const targetUrl = srvRes?.url || '';
    if (targetUrl) lastPreciseDashboardUrl = targetUrl;
    const copied = await copyTextToClipboardSafe(targetUrl);
    const hasSid = Boolean(focusTarget.sessionId);
    const copyNote = copied
      ? t(hasSid ? 'settings.dock.openRightCopiedSession' : 'settings.dock.openRightCopiedList')
      : t('settings.dock.openRightCopyFail');
    const shortTag = focusTarget.sessionId ? focusTarget.sessionId.slice(0, 8) : '';
    if (!hasSid) {
      setDockOpenFeedback(t('settings.dock.openRightNoSession', { copyNote }), true, { showActions: true });
    } else if (dockFallbackReason === 'aux') {
      setDockOpenFeedback(t('settings.dock.openRightFallback', { copyNote }), true, { showActions: true });
    } else {
      setDockOpenFeedback(t('settings.dock.openRightOk', {
        role: formatAuxRoleText(focusTarget),
        id: shortTag,
        copyNote
      }), false, { showActions: true });
    }
    syncAuxContextBar();
    return {
      ok: true,
      mode: dockFallbackReason === 'aux' ? 'fallback_copy' : 'aux_dock',
      url: targetUrl,
      copied,
      focusTarget
    };
  }

  async function openStandaloneBrowserPage() {
    try {
      const srvRes = await resolvePreciseDashboardUrl({ openExternal: true });
      if (!srvRes || !srvRes.ok || !srvRes.url) {
        console.warn('[Context Meter] 独立看板服务未就绪，放弃盲打默认端口');
        setDockOpenFeedback(t('settings.dock.openStandaloneNotReady'), true);
        return srvRes;
      }
      const targetUrl = String(srvRes.url);
      if (srvRes.openedExternal) {
        const sid = srvRes.focusTarget?.sessionId;
        setDockOpenFeedback(
          sid
            ? t('settings.dock.openStandaloneSessionOk', { id: sid.slice(0, 8) })
            : t('settings.dock.openStandaloneListOk'),
          !sid
        );
        return srvRes;
      }
      if (typeof window?.contextMeterAPI?.openExternal === 'function') {
        await window.contextMeterAPI.openExternal(targetUrl);
        return { ...srvRes, openedExternal: true };
      }
      if (typeof window?.contextMeterAPI?.openExternalUrl === 'function') {
        await window.contextMeterAPI.openExternalUrl(targetUrl);
        return { ...srvRes, openedExternal: true };
      }
      if (typeof window?.open === 'function') {
        window.open(targetUrl, '_blank');
      }
      return srvRes;
    } catch (e) {
      console.warn('[Context Meter] 打开浏览器看板失败:', e);
      return { ok: false, error: e.message };
    }
  }

  function findComposerControlsContainer() {
    try {
      if (typeof document?.querySelector !== 'function') return null;

      // 1. 寻找核心控制按钮
      // A. 发送按钮
      const sendBtn = document.querySelector(
        'button[aria-label*="Send" i], button[aria-label*="发送"], [data-testid*="send" i], button.send-button, form button[type="submit"]'
      );

      // B. 麦克风/语音按钮
      const micBtn = document.querySelector(
        'button[aria-label*="mic" i], button[aria-label*="麦克风"], button[aria-label*="voice" i], [data-testid*="voice" i], button[aria-label*="Audio" i]'
      );

      // C. 本地权限/运行模式按钮 (如"极速", "fast", "local", "permission", 包含盾牌图标的按钮)
      const allButtons = Array.from(document.querySelectorAll('button') || []);
      const permissionBtn = allButtons.find(b => {
        if (!b || b === sendBtn || b === micBtn) return false;
        const aria = (typeof b.getAttribute === 'function' ? (b.getAttribute('aria-label') || '') : '').toLowerCase();
        const text = String(b.textContent || '').trim().toLowerCase();
        const testId = (typeof b.getAttribute === 'function' ? (b.getAttribute('data-testid') || '') : '').toLowerCase();
        if (/permission|极速|权限|fast\b|local\b|auto\b/i.test(aria) || /permission|极速|权限/i.test(text) || /permission/i.test(testId)) {
          return true;
        }
        const svg = typeof b.querySelector === 'function' ? b.querySelector('svg') : null;
        if (svg && /shield|security|lock|bolt/i.test(svg.innerHTML || '')) return true;
        return false;
      });

      // D. 模型选择器按钮 (在左侧)
      const modelBtn = allButtons.find(b => {
        if (!b || b === sendBtn || b === micBtn || b === permissionBtn) return false;
        const text = String(b.textContent || '').trim();
        const aria = (typeof b.getAttribute === 'function' ? (b.getAttribute('aria-label') || '') : '').toLowerCase();
        return /Gemini|Claude|GPT|DeepSeek|Auto|模型|Model/i.test(text) || /model/i.test(aria);
      });

      // 2. 确定锚点元素 anchorBtn (状态条应放在其紧左侧)
      // 优先级：权限按钮 > 麦克风 > 发送按钮
      const anchorBtn = permissionBtn || micBtn || sendBtn;

      if (!anchorBtn) {
        const composer = document.querySelector('[data-testid="composer"], textarea');
        if (composer) {
          const parent = composer.closest('div[class*="composer"], div[class*="chat-input"]') || composer.parentElement;
          const bottomBar = parent?.querySelector?.('div.flex:last-child');
          if (bottomBar && bottomBar !== composer) {
            return { bar: bottomBar, insertBeforeNode: null, isRightGroup: false };
          }
        }
        return null;
      }

      // 3. 分析 anchorBtn 的父层级结构
      const directParent = anchorBtn.parentElement;
      if (!directParent || directParent === document.body) return null;

      // 检查 directParent 是否是右侧独立按钮组 (例如包含 permissionBtn, micBtn, sendBtn 的右侧 flex wrapper)
      // 如果 directParent 包含了 sendBtn 并且不包含 modelBtn，说明 directParent 就是右侧按钮组！
      if (modelBtn && !directParent.contains(modelBtn) && directParent.contains(sendBtn || anchorBtn)) {
        const targetInsertBefore = (permissionBtn && directParent.contains(permissionBtn))
          ? permissionBtn
          : (directParent.firstChild || anchorBtn);
        return {
          bar: directParent,
          insertBeforeNode: targetInsertBefore,
          modelBtn,
          isRightGroup: true
        };
      }

      // 单层扁平工具栏
      return {
        bar: directParent,
        insertBeforeNode: anchorBtn,
        modelBtn,
        isRightGroup: false
      };
    } catch {
      return null;
    }
  }

